Write idiomatic table-driven Go tests (`t.Run`) for `ingest/batch_handler.go` covering HTTP status codes, body size limits, slice aliasing invariance, and `errors.Is` wrapping:
```go
package ingest

import (
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
)

const MaxBodyBytes = 2048

var ErrEmptyMetrics = errors.New("empty metrics batch")

type Payload struct {
	Host    string   `json:"host"`
	Metrics []string `json:"metrics"`
}

func ParsePayload(w http.ResponseWriter, r *http.Request, defaultTags []string) ([]string, int, error) {
	if r.Method != http.MethodPost {
		return nil, http.StatusMethodNotAllowed, fmt.Errorf("method %s: not allowed", r.Method)
	}
	r.Body = http.MaxBytesReader(w, r.Body, MaxBodyBytes)
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	var p Payload
	if err := dec.Decode(&p); err != nil {
		var maxErr *http.MaxBytesError
		if errors.As(err, &maxErr) {
			return nil, http.StatusRequestEntityTooLarge, fmt.Errorf("read body: %w", err)
		}
		return nil, http.StatusBadRequest, fmt.Errorf("decode json: %w", err)
	}
	if len(p.Metrics) == 0 {
		return nil, http.StatusUnprocessableEntity, fmt.Errorf("validate batch: %w", ErrEmptyMetrics)
	}
	out := make([]string, 0, len(defaultTags)+len(p.Metrics))
	out = append(out, defaultTags...)
	out = append(out, p.Metrics...)
	return out, http.StatusAccepted, nil
}
```

