```rust
#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn from_str_rejects_malformed_and_zero_specs() {
        for bad in ["", "cap", "cap:", "cap:0", "cap:-5", "cap:18446744073709551616", "max:10", "cap:10:extra"] {
            assert_eq!(bad.parse::<QuotaValve>().err(), Some(ValveError::BadSpec), "input={bad}");
        }
        let ok = "cap:100".parse::<QuotaValve>().expect("valid spec");
        assert_eq!(ok.state, ValveState::Idle);
    }

    #[test]
    fn checked_overflow_and_cap_boundaries_return_none_without_mutating_used() {
        let mut v: QuotaValve = format!("cap:{}", u64::MAX - 10).parse().unwrap();
        v.transition(ValveState::Active).unwrap();

        assert_eq!(v.charge(100), Ok(Some(u64::MAX - 110)));
        // Overflowing u64::MAX via checked_add must yield Ok(None) and preserve state.
        assert_eq!(v.charge(u64::MAX - 50), Ok(None));
        // Exceeding limit without overflowing u64 must also yield Ok(None).
        assert_eq!(v.charge(u64::MAX - 109), Ok(None));
        // Exact remaining budget succeeds and leaves 0.
        assert_eq!(v.charge(u64::MAX - 110), Ok(Some(0)));
        assert_eq!(v.charge(1), Ok(None));
    }

    #[test]
    fn state_machine_forbids_skips_reversals_and_inactive_charges() {
        let mut v: QuotaValve = "cap:50".parse().unwrap();
        assert_eq!(v.charge(1), Err(ValveError::NotActive));
        assert_eq!(
            v.transition(ValveState::Sealed),
            Err(ValveError::InvalidTransition(ValveState::Idle, ValveState::Sealed))
        );

        v.transition(ValveState::Active).unwrap();
        assert_eq!(
            v.transition(ValveState::Idle),
            Err(ValveError::InvalidTransition(ValveState::Active, ValveState::Idle))
        );
        v.transition(ValveState::Draining).unwrap();
        assert_eq!(v.charge(1), Err(ValveError::NotActive));
        v.transition(ValveState::Sealed).unwrap();
        assert_eq!(
            v.transition(ValveState::Active),
            Err(ValveError::InvalidTransition(ValveState::Sealed, ValveState::Active))
        );
    }

    #[test]
    fn fixed_array_ring_never_heap_allocates_across_wraparound() {
        let mut v: QuotaValve = "cap:10000".parse().unwrap();
        v.transition(ValveState::Active).unwrap();
        let base_ptr = v.recent_ptr();
        for step in 1..=64_u64 {
            assert!(v.charge(step).unwrap().is_some());
            assert_eq!(v.recent_ptr(), base_ptr);
        }
        assert_eq!(std::mem::size_of_val(&v.recent), 32);
    }
}
