Write a Vitest security regression suite for `src/handlers/updateProfile.ts` covering Zod strict rejection of injected admin properties, `Origin` validation, `AbortSignal` cancellation, and rate-limit window reset via `vi.useFakeTimers()`:
```ts
import { z } from 'zod';

const ProfilePatchSchema = z.object({
  displayName: z.string().trim().min(2).max(40),
  bio: z.string().max(160).optional(),
}).strict();

const ALLOWED_ORIGINS = new Set(['https://app.internal.example', 'https://admin.internal.example']);
const WINDOW_MS = 60_000;
const MAX_UPDATES = 3;

export class GuardedProfileUpdater {
  private hits = new Map<string, { count: number; resetAt: number }>();

  constructor(private persist: (userId: string, data: unknown, signal?: AbortSignal) => Promise<void>) {}

  async handle(userId: string, origin: string | undefined, body: unknown, signal?: AbortSignal) {
    if (!origin || !ALLOWED_ORIGINS.has(origin)) {
      return { status: 403 as const, error: 'origin_denied' };
    }
    if (signal?.aborted) {
      throw new DOMException('Aborted', 'AbortError');
    }
    const now = Date.now();
    const slot = this.hits.get(userId);
    if (!slot || now >= slot.resetAt) {
      this.hits.set(userId, { count: 1, resetAt: now + WINDOW_MS });
    } else if (slot.count >= MAX_UPDATES) {
      return { status: 429 as const, error: 'rate_limited' };
    } else {
      slot.count += 1;
    }
    const parsed = ProfilePatchSchema.safeParse(body);
    if (!parsed.success) {
      return { status: 400 as const, error: 'validation_failed' };
    }
    await this.persist(userId, parsed.data, signal);
    return { status: 200 as const, data: parsed.data };
  }
}
