Write a transactional PostgreSQL invariant test script (`BEGIN ... ROLLBACK`) for the `escrow_holds` schema below verifying the `CHECK` bounds, `RLS` cross-tenant `0 rows` visibility under `SET LOCAL ROLE`, and the partial unique index on open holds:
```sql
CREATE TABLE escrow_holds (
    hold_id UUID PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    order_ref TEXT NOT NULL,
    held_cents BIGINT NOT NULL,
    released_cents BIGINT NOT NULL DEFAULT 0,
    status TEXT NOT NULL CHECK (status IN ('OPEN', 'RELEASED', 'CANCELLED')),
    CONSTRAINT positive_hold CHECK (held_cents > 0 AND released_cents >= 0 AND released_cents <= held_cents)
);

CREATE UNIQUE INDEX uniq_open_hold_per_order
    ON escrow_holds (tenant_id, order_ref)
    WHERE status = 'OPEN';

ALTER TABLE escrow_holds ENABLE ROW LEVEL SECURITY;
ALTER TABLE escrow_holds FORCE ROW LEVEL SECURITY;

CREATE POLICY tenant_isolation ON escrow_holds
    USING (tenant_id = current_setting('app.tenant_id', true))
    WITH CHECK (tenant_id = current_setting('app.tenant_id', true));
```

