```go
package ledger

import (
	"errors"
	"sync"
	"sync/atomic"
	"testing"
)

func TestTransferBidirectionalConservationAndNoDoubleSpend(t *testing.T) {
	book := NewAccountBook(map[string]int64{
		"acct_a": 10_000,
		"acct_b": 10_000,
		"acct_c": 10_000,
	})
	const initialTotal int64 = 30_000

	start := make(chan struct{})
	var wg sync.WaitGroup
	pairs := [][2]string{
		{"acct_a", "acct_b"},
		{"acct_b", "acct_a"},
		{"acct_b", "acct_c"},
		{"acct_c", "acct_b"},
		{"acct_c", "acct_a"},
		{"acct_a", "acct_c"},
	}

	for _, p := range pairs {
		for w := 0; w < 8; w++ {
			wg.Add(1)
			go func(src, dst string) {
				defer wg.Done()
				<-start
				for i := 0; i < 250; i++ {
					err := book.Transfer(src, dst, 7)
					if err != nil && !errors.Is(err, ErrInsufficientFunds) {
						t.Errorf("unexpected error: %v", err)
						return
					}
				}
			}(p[0], p[1])
		}
	}
	close(start)
	wg.Wait()

	gotTotal := int64(0)
	for _, id := range []string{"acct_a", "acct_b", "acct_c"} {
		bal := book.Balance(id)
		if bal < 0 {
			t.Fatalf("negative balance on %s: %d", id, bal)
		}
		gotTotal += bal
	}
	if gotTotal != initialTotal {
		t.Fatalf("total balance = %d, want %d", gotTotal, initialTotal)
	}

	// Exact single-spend race: 64 goroutines compete for 10 withdrawals of 100 cents from 1000 cents.
	raceBook := NewAccountBook(map[string]int64{"vault": 1_000, "sink": 0})
	fire := make(chan struct{})
	var wins atomic.Int32
	for g := 0; g < 64; g++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			<-fire
			if err := raceBook.Transfer("vault", "sink", 100); err == nil {
				wins.Add(1)
			}
		}()
	}
	close(fire)
	wg.Wait()

	if wins.Load() != 10 || raceBook.Balance("vault") != 0 || raceBook.Balance("sink") != 1_000 {
		t.Fatalf("double-spend or lost update: wins=%d vault=%d sink=%d", wins.Load(), raceBook.Balance("vault"), raceBook.Balance("sink"))
	}
}
