Write a Go RBAC security matrix test for `adminapi/key_rotation.go` covering `(unauthenticated, expired_token, wrong_tenant, viewer_role, auditor_role, key_admin_role)` and verifying fail-closed `401`/`403` behavior with zero store mutations:
```go
package adminapi

import (
	"context"
	"net/http"
	"time"
)

type Claims struct {
	Sub       string
	TenantID  string
	Role      string
	ExpiresAt time.Time
}

type ctxKey struct{}

func WithClaims(ctx context.Context, c *Claims) context.Context {
	return context.WithValue(ctx, ctxKey{}, c)
}

type KeyRotator interface {
	Rotate(tenantID string) error
}

func RotateTenantKeyHandler(rotator KeyRotator, now func() time.Time) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		targetTenant := r.PathValue("tenantID")
		claims, ok := r.Context().Value(ctxKey{}).(*Claims)
		if !ok || claims == nil || claims.Sub == "" {
			w.WriteHeader(http.StatusUnauthorized)
			return
		}
		if !now().Before(claims.ExpiresAt) {
			w.WriteHeader(http.StatusUnauthorized)
			return
		}
		if claims.TenantID != targetTenant || claims.Role != "key_admin" {
			w.WriteHeader(http.StatusForbidden)
			return
		}
		if err := rotator.Rotate(targetTenant); err != nil {
			w.WriteHeader(http.StatusInternalServerError)
			return
		}
		w.WriteHeader(http.StatusNoContent)
	}
}
