Write a Vitest suite for `src/net/resilientSend.ts` using a mocked upstream sequence (`503` -> `429` with `Retry-After: 1` -> `200`) and fake timers, verifying that `GET` and keyed `POST` retry properly while an unkeyed `POST` never retries on timeout or `503`:
```ts
export interface RequestSpec {
  method: 'GET' | 'POST';
  url: string;
  idempotencyKey?: string;
  timeoutMs: number;
}

export async function resilientSend(
  spec: RequestSpec,
  transport: (url: string, init: RequestInit) => Promise<Response>,
): Promise<Response> {
  const canRetry = spec.method === 'GET' || Boolean(spec.idempotencyKey);
  const maxAttempts = canRetry ? 3 : 1;

  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), spec.timeoutMs);
    try {
      const headers: Record<string, string> = {};
      if (spec.idempotencyKey) headers['Idempotency-Key'] = spec.idempotencyKey;
      const resp = await transport(spec.url, { method: spec.method, headers, signal: ctrl.signal });
      if (resp.status < 500 && resp.status !== 429) return resp;
      if (attempt === maxAttempts) return resp;
      const retryHeader = Number(resp.headers.get('Retry-After'));
      const delayMs = Number.isFinite(retryHeader) && retryHeader > 0 ? retryHeader * 1000 : 200 * attempt;
      await new Promise((r) => setTimeout(r, delayMs));
    } catch (err) {
      if (attempt === maxAttempts) throw err;
      await new Promise((r) => setTimeout(r, 200 * attempt));
    } finally {
      clearTimeout(timer);
    }
  }
  throw new Error('unreachable');
}
