Write a Rust `#[cfg(test)] mod tests` suite for `FeePolicy` verifying `checked_mul` overflow returning `None`, `FromStr` malformed input rejection, `Lifecycle` invalid state transitions, and stack-only `[u64; 8]` audit log zero-allocation invariants:
```rust
use std::str::FromStr;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Lifecycle {
    Staged,
    Live,
    Frozen,
    Retired,
}

#[derive(Debug, PartialEq, Eq)]
pub enum FeeError {
    ParseError,
    BadTransition(Lifecycle, Lifecycle),
    PolicyNotLive,
}

pub struct FeePolicy {
    bps: u128,
    phase: Lifecycle,
    samples: [u64; 8],
    idx: usize,
}

impl FromStr for FeePolicy {
    type Err = FeeError;
    fn from_str(raw: &str) -> Result<Self, Self::Err> {
        let rest = raw.strip_prefix("bps=").ok_or(FeeError::ParseError)?;
        let bps: u128 = rest.parse().map_err(|_| FeeError::ParseError)?;
        if bps == 0 || bps > 10_000 {
            return Err(FeeError::ParseError);
        }
        Ok(Self { bps, phase: Lifecycle::Staged, samples: [0; 8], idx: 0 })
    }
}

impl FeePolicy {
    pub fn advance(&mut self, to: Lifecycle) -> Result<(), FeeError> {
        let allowed = matches!(
            (self.phase, to),
            (Lifecycle::Staged, Lifecycle::Live)
                | (Lifecycle::Live, Lifecycle::Frozen)
                | (Lifecycle::Frozen, Lifecycle::Live)
                | (Lifecycle::Frozen, Lifecycle::Retired)
        );
        if !allowed {
            return Err(FeeError::BadTransition(self.phase, to));
        }
        self.phase = to;
        Ok(())
    }

    pub fn quote_fee(&mut self, amount: u128) -> Result<Option<u128>, FeeError> {
        if self.phase != Lifecycle::Live {
            return Err(FeeError::PolicyNotLive);
        }
        let Some(prod) = amount.checked_mul(self.bps) else {
            return Ok(None);
        };
        let fee = prod / 10_000;
        self.samples[self.idx & 7] = fee.min(u64::MAX as u128) as u64;
        self.idx = self.idx.wrapping_add(1);
        Ok(Some(fee))
    }

    pub fn samples_addr(&self) -> usize {
        self.samples.as_ptr() as usize
    }
}
