        let mut p: FeePolicy = "bps=250".parse().unwrap();
        p.advance(Lifecycle::Live).unwrap();

        assert_eq!(p.quote_fee(0), Ok(Some(0)));
        assert_eq!(p.quote_fee(40_000), Ok(Some(1_000)));
        let max_safe = u128::MAX / 250;
        assert!(p.quote_fee(max_safe).unwrap().is_some());
        assert_eq!(p.quote_fee(max_safe + 1), Ok(None));
        assert_eq!(p.quote_fee(u128::MAX), Ok(None));
