Write a `pytest` suite for `clients/shipping_client.py` simulating `503` -> `429` (`Retry-After: 2`) -> `200` with an injectable `sleep_fn`, verifying backoff delays on `GET` and keyed `POST`, while proving unkeyed `POST` never retries on `TimeoutError` or `503`:
```python
from dataclasses import dataclass
from typing import Callable

@dataclass
class RawHttpResponse:
    status: int
    headers: dict[str, str]
    body: str

class ShippingClient:
    def __init__(
        self,
        send_fn: Callable[[str, str, dict[str, str], float], RawHttpResponse],
        sleep_fn: Callable[[float], None],
        timeout_sec: float = 1.5,
    ) -> None:
        self._send = send_fn
        self._sleep = sleep_fn
        self._timeout = timeout_sec

    def request(self, method: str, path: str, idem_key: str | None = None) -> RawHttpResponse:
        method_u = method.upper()
        retryable = method_u in {'GET', 'HEAD'} or bool(idem_key)
        max_tries = 3 if retryable else 1
        headers = {'Idempotency-Key': idem_key} if idem_key else {}

        for attempt in range(1, max_tries + 1):
            try:
                resp = self._send(method_u, path, dict(headers), self._timeout)
            except TimeoutError:
                if attempt == max_tries:
                    raise
                self._sleep(0.25 * attempt)
                continue

            if resp.status < 500 and resp.status != 429:
                return resp
            if attempt == max_tries:
                return resp
            ra = resp.headers.get('Retry-After', '')
            delay = float(ra) if ra.isdigit() and int(ra) > 0 else 0.25 * attempt
            self._sleep(delay)
        raise RuntimeError('unreachable')
