    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let (start_s, max_s) = s.split_once('/').ok_or(LeaseErr::InvalidFormat)?;
        let start: u64 = start_s.parse().map_err(|_| LeaseErr::InvalidFormat)?;
        let max: u64 = max_s.parse().map_err(|_| LeaseErr::InvalidFormat)?;
        if start == 0 || max < start {
            return Err(LeaseErr::InvalidFormat);
        }
        Ok(Self { max_deadline_ms: max, expires_ms: start, state: LeaseState::Pending, deltas: [0; 8], slot: 0 })
    }
}

impl LeaseTracker {
    pub fn set_state(&mut self, next: LeaseState) -> Result<(), LeaseErr> {
        let valid = matches!(
            (self.state, next),
            (LeaseState::Pending, LeaseState::Granted) | (LeaseState::Granted, LeaseState::Revoked)
        );
        if !valid {
            return Err(LeaseErr::IllegalTransition(self.state, next));
        }
        self.state = next;
        Ok(())
    }

    pub fn renew(&mut self, add_ms: u32) -> Result<Option<u64>, LeaseErr> {
        if self.state != LeaseState::Granted {
            return Err(LeaseErr::NotGranted);
        }
        let Some(next_exp) = self.expires_ms.checked_add(u64::from(add_ms)) else {
            return Ok(None);
        };
        if next_exp > self.max_deadline_ms {
            return Ok(None);
        }
        self.expires_ms = next_exp;
        self.deltas[self.slot & 7] = add_ms;
        self.slot = self.slot.wrapping_add(1);
        Ok(Some(self.expires_ms))
    }

    pub fn deltas_ptr(&self) -> *const u32 {
        self.deltas.as_ptr()
    }
}
