```ts
import { z } from 'zod';

const HookConfigSchema = z.object({
  targetUrl: z.string().url().startsWith('https://'),
  events: z.array(z.enum(['invoice.paid', 'subscription.canceled'])).min(1),
}).strict();

const ALLOWED_DASHBOARD_ORIGINS = new Set(['https://dashboard.pay.example']);

export class WebhookRegistry {
  private buckets = new Map<string, { count: number; resetAt: number }>();

  constructor(private probeAndSave: (orgId: string, url: string, signal?: AbortSignal) => Promise<string>) {}

  async register(orgId: string, origin: string | undefined, payload: unknown, signal?: AbortSignal) {
    if (!origin || !ALLOWED_DASHBOARD_ORIGINS.has(origin)) {
      return { status: 403 as const, code: 'forbidden_origin' };
    }
    const check = HookConfigSchema.safeParse(payload);
    if (!check.success) {
      return { status: 400 as const, code: 'invalid_hook_config' };
    }
    const now = Date.now();
    const bucket = this.buckets.get(orgId);
    if (!bucket || now >= bucket.resetAt) {
      this.buckets.set(orgId, { count: 1, resetAt: now + 120_000 });
    } else if (bucket.count >= 2) {
      return { status: 429 as const, code: 'hook_rate_exceeded' };
    } else {
      bucket.count += 1;
    }
    signal?.throwIfAborted();
    const hookId = await this.probeAndSave(orgId, check.data.targetUrl, signal);
    return { status: 201 as const, hookId };
  }
}
