```rust
use std::sync::atomic::{AtomicU64, Ordering};

pub struct AtomicInventory {
    available: AtomicU64,
}

impl AtomicInventory {
    pub const fn new(initial: u64) -> Self {
        Self { available: AtomicU64::new(initial) }
    }

    pub fn try_claim(&self, qty: u64) -> bool {
        if qty == 0 {
            return false;
        }
        self.available
            .fetch_update(Ordering::AcqRel, Ordering::Acquire, |cur| cur.checked_sub(qty))
            .is_ok()
    }

    pub fn remaining(&self) -> u64 {
        self.available.load(Ordering::Acquire)
    }
}
