Write a Go unit test suite for `jwtlite/header_codec.go` testing `DecodeHeader(EncodeHeader(h)) == h` round-trips and rejecting padded `=`, standard base64 `+/` characters, truncated segments, unknown fields, and `"alg":"none"`:
```go
package jwtlite

import (
	"bytes"
	"encoding/base64"
	"encoding/json"
	"errors"
)

type ProtectedHeader struct {
	Alg string `json:"alg"`
	Kid string `json:"kid"`
	Typ string `json:"typ"`
}

func EncodeHeader(h ProtectedHeader) (string, error) {
	if h.Alg != "EdDSA" && h.Alg != "ES256" {
		return "", errors.New("unsupported alg")
	}
	if h.Kid == "" || h.Typ != "JWT" {
		return "", errors.New("missing kid or invalid typ")
	}
	raw, err := json.Marshal(h)
	if err != nil {
		return "", err
	}
	return base64.RawURLEncoding.EncodeToString(raw), nil
}

func DecodeHeader(seg string) (ProtectedHeader, error) {
	if seg == "" || len(seg) > 512 {
		return ProtectedHeader{}, errors.New("invalid segment length")
	}
	raw, err := base64.RawURLEncoding.Strict().DecodeString(seg)
	if err != nil {
		return ProtectedHeader{}, err
	}
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.DisallowUnknownFields()
	var h ProtectedHeader
	if err := dec.Decode(&h); err != nil || dec.More() {
		return ProtectedHeader{}, errors.New("malformed header json")
	}
	if (h.Alg != "EdDSA" && h.Alg != "ES256") || h.Kid == "" || h.Typ != "JWT" {
		return ProtectedHeader{}, errors.New("disallowed header claims")
	}
	return h, nil
}
