export interface SessionToken {
  sub: string;
  tenantId: string;
  role: 'viewer' | 'editor' | 'data_owner';
  expMs: number;
}

export async function purgeDatasetHandler(
  token: SessionToken | null,
  targetTenantId: string,
  datasetId: string,
  nowMs: number,
  purgeFn: (tenantId: string, datasetId: string) => Promise<void>,
): Promise<{ status: 204 | 401 | 403; error?: string }> {
  if (!token || !token.sub) {
    return { status: 401, error: 'missing_credentials' };
  }
  if (nowMs >= token.expMs) {
    return { status: 401, error: 'session_expired' };
  }
  if (token.tenantId !== targetTenantId) {
    return { status: 403, error: 'tenant_mismatch' };
  }
  if (token.role !== 'data_owner') {
    return { status: 403, error: 'role_forbidden' };
  }
  await purgeFn(targetTenantId, datasetId);
  return { status: 204 };
}
