Write a Go test suite using `httptest.NewServer` for `rpcclient/dispatch.go` simulating `503` -> `429` (`Retry-After: 1`) -> `200`, verifying keyed `POST` retries cleanly while unkeyed `POST` does NOT retry on client timeout or `503`:
```go
package rpcclient

import (
	"bytes"
	"context"
	"net/http"
	"strconv"
	"time"
)

type Dispatcher struct {
	Client     *http.Client
	PerTryWait time.Duration
	Sleep      func(time.Duration)
}

func (d *Dispatcher) Do(ctx context.Context, method, url, idemKey string, body []byte) (*http.Response, error) {
	canRetry := method == http.MethodGet || idemKey != ""
	maxTries := 1
	if canRetry {
		maxTries = 3
	}
	for attempt := 1; attempt <= maxTries; attempt++ {
		tryCtx, cancel := context.WithTimeout(ctx, d.PerTryWait)
		req, err := http.NewRequestWithContext(tryCtx, method, url, bytes.NewReader(body))
		if err != nil {
			cancel()
			return nil, err
		}
		if idemKey != "" {
			req.Header.Set("Idempotency-Key", idemKey)
		}
		resp, err := d.Client.Do(req)
		cancel()
		if err != nil {
			if attempt == maxTries {
				return nil, err
			}
			d.Sleep(50 * time.Millisecond)
			continue
		}
		if (resp.StatusCode < 500 && resp.StatusCode != http.StatusTooManyRequests) || attempt == maxTries {
			return resp, nil
		}
		_ = resp.Body.Close()
		wait := 50 * time.Millisecond
		if sec, err := strconv.Atoi(resp.Header.Get("Retry-After")); err == nil && sec > 0 {
			wait = time.Duration(sec) * time.Second
		}
		d.Sleep(wait)
	}
	return nil, context.Canceled
}
