			w.WriteHeader(http.StatusTooManyRequests)
		default:
			w.WriteHeader(http.StatusOK)
		}
	}))
	defer srv.Close()

	var sleeps []time.Duration
	d := &Dispatcher{
		Client:     srv.Client(),
		PerTryWait: 200 * time.Millisecond,
		Sleep:      func(dur time.Duration) { sleeps = append(sleeps, dur) },
	}
	resp, err := d.Do(context.Background(), http.MethodPost, srv.URL, "ik-42", []byte(`{"op":"debit"}`))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK || hits.Load() != 3 {
		t.Fatalf("status=%d hits=%d, want 200 and 3", resp.StatusCode, hits.Load())
	}
	wantSleeps := []time.Duration{50 * time.Millisecond, time.Second}
	if !reflect.DeepEqual(sleeps, wantSleeps) {
		t.Fatalf("sleeps = %v, want %v", sleeps, wantSleeps)
	}
}

func TestUnkeyedPostDoesNotRetryOnTimeoutOr503(t *testing.T) {
	var timeoutHits atomic.Int32
	unblock := make(chan struct{})
	slowSrv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		timeoutHits.Add(1)
		<-unblock
	}))
	defer func() {
		close(unblock)
		slowSrv.Close()
	}()

	d := &Dispatcher{
		Client:     slowSrv.Client(),
		PerTryWait: 25 * time.Millisecond,
		Sleep:      func(time.Duration) { t.Errorf("unkeyed POST must not sleep/retry") },
	}
	if _, err := d.Do(context.Background(), http.MethodPost, slowSrv.URL, "", []byte(`{"op":"mint"}`)); err == nil {
		t.Fatalf("expected timeout error on unkeyed POST")
	}
	if timeoutHits.Load() != 1 {
		t.Fatalf("timeoutHits = %d, want 1", timeoutHits.Load())
	}

	var err503Hits atomic.Int32
	busySrv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		err503Hits.Add(1)
		w.WriteHeader(http.StatusServiceUnavailable)
	}))
	defer busySrv.Close()
	resp, err := d.Do(context.Background(), http.MethodPost, busySrv.URL, "", []byte(`{}`))
	if err != nil || resp.StatusCode != http.StatusServiceUnavailable || err503Hits.Load() != 1 {
		t.Fatalf("got err=%v code=%v hits=%d", err, resp.StatusCode, err503Hits.Load())
	}
	resp.Body.Close()
