Write a `pytest.mark.parametrize` boundary and security regression suite for `tokens/presigned_download.py`:
```python
from pathlib import PurePosixPath

MAX_BLOB_BYTES = 52_428_800

class GrantValidationError(ValueError):
    pass

def verify_download_grant(
    blob_key: str,
    max_bytes: int,
    expires_epoch: int,
    now_epoch: int,
    download_name: str,
) -> tuple[str, str]:
    if not blob_key or blob_key.startswith('/') or '\\' in blob_key:
        raise GrantValidationError('invalid blob key')
    parts = PurePosixPath(blob_key).parts
    if '..' in parts or '.' in parts:
        raise GrantValidationError('traversal in blob key')
    if isinstance(max_bytes, bool) or not (1 <= max_bytes <= MAX_BLOB_BYTES):
        raise GrantValidationError('byte quota out of bounds')
    if now_epoch >= expires_epoch:
        raise GrantValidationError('grant expired')
    if not download_name or any(c in download_name for c in ('\r', '\n', '"', '/', '\\')):
        raise GrantValidationError('unsafe download name')
    if len(download_name.encode('utf-8')) > 120:
        raise GrantValidationError('download name too long')
    return PurePosixPath(*parts).as_posix(), download_name
