```go
package coupon

import (
	"errors"
	"sync"
)

var (
	ErrExhausted      = errors.New("coupon pool exhausted")
	ErrAlreadyClaimed = errors.New("user already claimed")
)

type CouponPool struct {
	mu        sync.Mutex
	maxClaims int
	claimants map[string]struct{}
}

func NewCouponPool(maxClaims int) *CouponPool {
	return &CouponPool{maxClaims: maxClaims, claimants: make(map[string]struct{})}
}

func (p *CouponPool) Claim(userID string) error {
	p.mu.Lock()
	defer p.mu.Unlock()
	if _, exists := p.claimants[userID]; exists {
		return ErrAlreadyClaimed
	}
	if len(p.claimants) >= p.maxClaims {
		return ErrExhausted
	}
	p.claimants[userID] = struct{}{}
	return nil
}

func (p *CouponPool) Count() int {
	p.mu.Lock()
	defer p.mu.Unlock()
	return len(p.claimants)
}
