```rust
use std::collections::HashMap;

#[derive(Debug, PartialEq, Eq)]
pub enum GateErr {
    EmptyKey,
    Conflict409,
}

#[derive(Debug, PartialEq, Eq)]
pub enum GateResult {
    Executed(u64),
    Replayed(u64),
}

pub struct IdempotentWireGate {
    next_seq: u64,
    seen: HashMap<String, ((String, u64), u64)>,
}

impl Default for IdempotentWireGate {
    fn default() -> Self {
        Self { next_seq: 1, seen: HashMap::new() }
    }
}

impl IdempotentWireGate {
    pub fn submit(&mut self, idem_key: &str, dest: &str, amount: u64) -> Result<GateResult, GateErr> {
        if idem_key.trim().is_empty() {
            return Err(GateErr::EmptyKey);
        }
        if let Some(((prev_dest, prev_amt), seq)) = self.seen.get(idem_key) {
            if prev_dest != dest || *prev_amt != amount {
                return Err(GateErr::Conflict409);
            }
            return Ok(GateResult::Replayed(*seq));
        }
        let assigned = self.next_seq;
        self.next_seq += 1;
        self.seen.insert(idem_key.to_string(), ((dest.to_string(), amount), assigned));
        Ok(GateResult::Executed(assigned))
    }

    pub fn committed_count(&self) -> u64 {
        self.next_seq - 1
    }
}
