Write a Vitest suite for `src/clients/kmsTransitClient.ts` mocking `503` -> `429` (`Retry-After: 3`) -> `200` with `vi.useFakeTimers()`, verifying `GET` and keyed `POST` retry with exact `Retry-After` timing while unkeyed `POST` never retries on timeout:
```ts
export async function callKmsEndpoint(
  method: 'GET' | 'POST',
  path: string,
  opts: { idemKey?: string; timeoutMs: number },
  doFetch: (path: string, init: RequestInit) => Promise<Response>,
): Promise<Response> {
  const safeToRetry = method === 'GET' || Boolean(opts.idemKey);
  const limit = safeToRetry ? 3 : 1;

  for (let i = 1; i <= limit; i++) {
    const ac = new AbortController();
    const tid = setTimeout(() => ac.abort(), opts.timeoutMs);
    try {
      const headers: Record<string, string> = opts.idemKey ? { 'Idempotency-Key': opts.idemKey } : {};
      const res = await doFetch(path, { method, headers, signal: ac.signal });
      if ((res.status < 500 && res.status !== 429) || i === limit) {
        return res;
      }
      const raSec = Number.parseInt(res.headers.get('Retry-After') ?? '', 10);
      const backoffMs = Number.isFinite(raSec) && raSec > 0 ? raSec * 1000 : 300 * i;
      await new Promise((r) => setTimeout(r, backoffMs));
    } catch (e) {
      if (i === limit) throw e;
      await new Promise((r) => setTimeout(r, 300 * i));
    } finally {
      clearTimeout(tid);
    }
  }
  throw new Error('exhausted');
}
