Write a Rust `#[cfg(test)] mod tests` suite for `CircuitMonitor` checking `checked_add` overflow returning `None`, `FromStr` malformed input rejection, `BreakerPhase` invalid state transitions, and zero-allocation fixed-ring latency storage:
```rust
use std::str::FromStr;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BreakerPhase {
    Closed,
    Tripped,
    HalfOpen,
}

#[derive(Debug, PartialEq, Eq)]
pub enum MonitorErr {
    BadConfig,
    IllegalJump(BreakerPhase, BreakerPhase),
    CircuitTripped,
}

pub struct CircuitMonitor {
    budget_us: u64,
    accum_us: u64,
    phase: BreakerPhase,
    lat_ring: [u32; 8],
    pos: usize,
}

impl FromStr for CircuitMonitor {
    type Err = MonitorErr;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let num_s = s.strip_prefix("budget_us=").ok_or(MonitorErr::BadConfig)?;
        let budget_us: u64 = num_s.parse().map_err(|_| MonitorErr::BadConfig)?;
        if budget_us == 0 {
            return Err(MonitorErr::BadConfig);
        }
        Ok(Self { budget_us, accum_us: 0, phase: BreakerPhase::Closed, lat_ring: [0; 8], pos: 0 })
    }
}

impl CircuitMonitor {
    pub fn shift(&mut self, next: BreakerPhase) -> Result<(), MonitorErr> {
        let ok = matches!(
            (self.phase, next),
            (BreakerPhase::Closed, BreakerPhase::Tripped)
                | (BreakerPhase::Tripped, BreakerPhase::HalfOpen)
                | (BreakerPhase::HalfOpen, BreakerPhase::Closed)
                | (BreakerPhase::HalfOpen, BreakerPhase::Tripped)
        );
        if !ok {
            return Err(MonitorErr::IllegalJump(self.phase, next));
        }
        if next == BreakerPhase::Closed {
            self.accum_us = 0;
        }
        self.phase = next;
        Ok(())
    }

    pub fn record_latency(&mut self, sample_us: u64) -> Result<Option<u64>, MonitorErr> {
        if self.phase == BreakerPhase::Tripped {
            return Err(MonitorErr::CircuitTripped);
        }
        let Some(sum) = self.accum_us.checked_add(sample_us) else {
            return Ok(None);
        };
        if sum > self.budget_us {
            return Ok(None);
        }
        self.accum_us = sum;
        self.lat_ring[self.pos & 7] = sample_us.min(u32::MAX as u64) as u32;
        self.pos = self.pos.wrapping_add(1);
        Ok(Some(self.accum_us))
    }

    pub fn ring_ptr(&self) -> *const u32 {
        self.lat_ring.as_ptr()
    }
}
```

