Write a multi-thread `pytest` stress test using `threading.Barrier` and `ThreadPoolExecutor` proving `CreditFacility` never over-draws past `limit_cents` or loses repayments under 32-thread contention:
```python
import threading

class CreditFacility:
    def __init__(self, limit_cents: int) -> None:
        self._lock = threading.Lock()
        self._limit = limit_cents
        self._drawn = 0

    def try_draw(self, cents: int) -> bool:
        if cents <= 0:
            return False
        with self._lock:
            if self._drawn + cents > self._limit:
                return False
            self._drawn += cents
            return True

    def repay(self, cents: int) -> None:
        if cents <= 0:
            raise ValueError('repay must be positive')
        with self._lock:
            if cents > self._drawn:
                raise ValueError('over-repayment')
            self._drawn -= cents

    def snapshot(self) -> tuple[int, int]:
        with self._lock:
            return self._drawn, self._limit - self._drawn
