Write a `pytest` round-trip and malformed-frame rejection suite for the length-prefixed CRC32 record codec `kv/netstring_crc.py` below:
```python
import zlib

class RecordSyntaxError(ValueError):
    pass

def _parse_len(prefix: bytes) -> int:
    if not prefix or not prefix.isdigit() or (len(prefix) > 1 and prefix[0:1] == b'0'):
        raise RecordSyntaxError('non-canonical length')
    return int(prefix)

def encode_record(key: str, val: bytes) -> bytes:
    kb = key.encode('utf-8')
    core = f'{len(kb)}:'.encode() + kb + f',{len(val)}:'.encode() + val
    crc = f'{zlib.crc32(core) & 0xFFFFFFFF:08x}'.encode('ascii')
    return core + b'#' + crc + b';'

def decode_record(frame: bytes) -> tuple[str, bytes]:
    if len(frame) < 13 or not frame.endswith(b';') or frame[-10:-9] != b'#':
        raise RecordSyntaxError('malformed trailer')
    core = frame[:-10]
    crc_hex = frame[-9:-1]
    try:
        want_crc = int(crc_hex.decode('ascii'), 16)
    except ValueError as exc:
        raise RecordSyntaxError('bad crc hex') from exc
    if (zlib.crc32(core) & 0xFFFFFFFF) != want_crc:
        raise RecordSyntaxError('crc mismatch')
    colon1 = core.find(b':')
    if colon1 <= 0:
        raise RecordSyntaxError('missing key length')
    klen = _parse_len(core[:colon1])
    k_end = colon1 + 1 + klen
    if core[k_end:k_end + 1] != b',':
        raise RecordSyntaxError('missing key delimiter')
    colon2 = core.find(b':', k_end + 1)
    if colon2 <= k_end + 1:
        raise RecordSyntaxError('missing val length')
    vlen = _parse_len(core[k_end + 1:colon2])
    val = core[colon2 + 1:]
    if len(val) != vlen:
        raise RecordSyntaxError('value length mismatch')
    return core[colon1 + 1:k_end].decode('utf-8'), val
```

