Write a `pytest` suite for `webhooks/event_sink.py` verifying cached replay on duplicate `Idempotency-Key` deliveries, single downstream dispatch, and `409` conflict rejection when a retried webhook mutates `event_type` or `amount_minor`:
```python
from typing import Callable

class WebhookConflictError(Exception):
    http_status = 409

class WebhookDeduplicator:
    def __init__(self, handler: Callable[[str, int], str]) -> None:
        self._handler = handler
        self._ledger: dict[str, tuple[tuple[str, int], dict]] = {}

    def ingest(self, idem_key: str, event_type: str, amount_minor: int) -> tuple[int, dict]:
        key = idem_key.strip()
        if not key:
            raise ValueError('missing idempotency key')
        sig = (event_type, amount_minor)
        if key in self._ledger:
            orig_sig, saved = self._ledger[key]
            if orig_sig != sig:
                raise WebhookConflictError('mutated webhook body for existing key')
            return 200, dict(saved)
        receipt = self._handler(event_type, amount_minor)
        out = {'receipt': receipt, 'replayed': False}
        self._ledger[key] = (sig, {'receipt': receipt, 'replayed': True})
        return 202, out
