Write table-driven Go tests (`t.Run`) for `oauth/redirect_register.go` verifying HTTP status codes, the 2 KiB body cap, `defaultURIs` slice non-aliasing, and `errors.Is` wrapping on insecure or fragmented redirect URIs:
```go
package oauth

import (
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"net/url"
)

const MaxClientRegBytes = 2048

var ErrUnsafeRedirectURI = errors.New("redirect_uri must use https without fragment")

type ClientReg struct {
	RedirectURIs []string `json:"redirect_uris"`
}

func RegisterRedirects(w http.ResponseWriter, r *http.Request, defaultURIs []string) ([]string, int, error) {
	if r.Method != http.MethodPost {
		return nil, http.StatusMethodNotAllowed, fmt.Errorf("method %s disallowed", r.Method)
	}
	r.Body = http.MaxBytesReader(w, r.Body, MaxClientRegBytes)
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	var reg ClientReg
	if err := dec.Decode(&reg); err != nil {
		var maxErr *http.MaxBytesError
		if errors.As(err, &maxErr) {
			return nil, http.StatusRequestEntityTooLarge, fmt.Errorf("reg body: %w", err)
		}
		return nil, http.StatusBadRequest, fmt.Errorf("reg decode: %w", err)
	}
	for _, raw := range reg.RedirectURIs {
		u, err := url.Parse(raw)
		if err != nil || u.Scheme != "https" || u.Host == "" || u.Fragment != "" {
			return nil, http.StatusUnprocessableEntity, fmt.Errorf("uri %q: %w", raw, ErrUnsafeRedirectURI)
		}
	}
	all := make([]string, 0, len(defaultURIs)+len(reg.RedirectURIs))
	all = append(all, defaultURIs...)
	all = append(all, reg.RedirectURIs...)
	return all, http.StatusCreated, nil
}
