Write a Rust `#[cfg(test)] mod tests` suite for `EpochRewardPool` verifying `checked_mul` overflow returning `None`, `FromStr` malformed rate rejection, `EpochState` invalid transitions, and zero-allocation fixed-array checkpointing:
```rust
use std::str::FromStr;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EpochState {
    Warmup,
    Accruing,
    Cooldown,
    Finalized,
}

#[derive(Debug, PartialEq, Eq)]
pub enum RewardErr {
    BadRate,
    InvalidTransition(EpochState, EpochState),
    NotAccruing,
}

pub struct EpochRewardPool {
    ppm: u64,
    state: EpochState,
    checkpoints: [u64; 4],
    head: usize,
}

impl FromStr for EpochRewardPool {
    type Err = RewardErr;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let v = s.strip_prefix("ppm:").ok_or(RewardErr::BadRate)?;
        let ppm: u64 = v.parse().map_err(|_| RewardErr::BadRate)?;
        if ppm == 0 || ppm > 1_000_000 {
            return Err(RewardErr::BadRate);
        }
        Ok(Self { ppm, state: EpochState::Warmup, checkpoints: [0; 4], head: 0 })
    }
}

impl EpochRewardPool {
    pub fn transition(&mut self, to: EpochState) -> Result<(), RewardErr> {
        let ok = matches!(
            (self.state, to),
            (EpochState::Warmup, EpochState::Accruing)
                | (EpochState::Accruing, EpochState::Cooldown)
                | (EpochState::Cooldown, EpochState::Finalized)
        );
        if !ok {
            return Err(RewardErr::InvalidTransition(self.state, to));
        }
        self.state = to;
        Ok(())
    }

    pub fn accrue(&mut self, stake: u64) -> Result<Option<u64>, RewardErr> {
        if self.state != EpochState::Accruing {
            return Err(RewardErr::NotAccruing);
        }
        let Some(prod) = stake.checked_mul(self.ppm) else {
            return Ok(None);
        };
        let reward = prod / 1_000_000;
        self.checkpoints[self.head & 3] = reward;
        self.head = self.head.wrapping_add(1);
        Ok(Some(reward))
    }

    pub fn checkpoints_ptr(&self) -> *const u64 {
        self.checkpoints.as_ptr()
    }
}
```

