mod tests {
    use super::*;

    #[test]
    fn from_str_rejects_out_of_range_and_malformed_ppm() {
        for bad in ["", "100", "ppm:", "ppm:0", "ppm:1000001", "ppm:-5", "ppm:12.5"] {
            assert_eq!(bad.parse::<EpochRewardPool>().err(), Some(RewardErr::BadRate), "raw={bad}");
        }
        assert!("ppm:1".parse::<EpochRewardPool>().is_ok());
        assert!("ppm:1000000".parse::<EpochRewardPool>().is_ok());
    }

    #[test]
    fn accrue_returns_none_on_checked_mul_overflow_and_computes_exact_ppm() {
        let mut pool: EpochRewardPool = "ppm:2500".parse().unwrap();
        pool.transition(EpochState::Accruing).unwrap();

        assert_eq!(pool.accrue(0), Ok(Some(0)));
        assert_eq!(pool.accrue(2_000_000), Ok(Some(5_000)));
        let max_safe = u64::MAX / 2500;
        assert!(pool.accrue(max_safe).unwrap().is_some());
        assert_eq!(pool.accrue(max_safe + 1), Ok(None));
    }

    #[test]
    fn state_machine_blocks_skips_reversals_and_non_accruing_calls() {
        let mut pool: EpochRewardPool = "ppm:500".parse().unwrap();
        assert_eq!(pool.accrue(1_000), Err(RewardErr::NotAccruing));
        assert_eq!(
            pool.transition(EpochState::Cooldown),
            Err(RewardErr::InvalidTransition(EpochState::Warmup, EpochState::Cooldown))
        );

        pool.transition(EpochState::Accruing).unwrap();
        pool.transition(EpochState::Cooldown).unwrap();
        assert_eq!(pool.accrue(1_000), Err(RewardErr::NotAccruing));
        pool.transition(EpochState::Finalized).unwrap();
        assert_eq!(
            pool.transition(EpochState::Accruing),
            Err(RewardErr::InvalidTransition(EpochState::Finalized, EpochState::Accruing))
        );
    }

    #[test]
    fn fixed_checkpoint_array_wraps_with_zero_heap_allocations() {
        let mut pool: EpochRewardPool = "ppm:1000".parse().unwrap();
        pool.transition(EpochState::Accruing).unwrap();
        let ptr = pool.checkpoints_ptr();
        for step in 1..=32_u64 {
            assert!(pool.accrue(step * 1_000_000).unwrap().is_some());
            assert_eq!(pool.checkpoints_ptr(), ptr);
        }
    }
}
