```ts
import { z } from 'zod';

const ToggleSchema = z.object({
  flagKey: z.string().regex(/^[a-z][a-z0-9_]{2,30}$/),
  enabled: z.boolean(),
}).strict();

const OPS_ORIGINS = new Set(['https://ops.control.internal']);

export class KillSwitchController {
  private cooldowns = new Map<string, number>();

  constructor(private publishToggle: (env: string, key: string, on: boolean, sig?: AbortSignal) => Promise<void>) {}

  async toggle(env: string, origin: string | undefined, body: unknown, signal?: AbortSignal) {
    if (!origin || !OPS_ORIGINS.has(origin)) {
      return { status: 403 as const, error: 'bad_ops_origin' };
    }
    const parsed = ToggleSchema.safeParse(body);
    if (!parsed.success) {
      return { status: 400 as const, error: 'invalid_toggle_body' };
    }
    const now = Date.now();
    const lockKey = `${env}:${parsed.data.flagKey}`;
    const until = this.cooldowns.get(lockKey) ?? 0;
    if (now < until) {
      return { status: 429 as const, error: 'toggle_in_cooldown' };
    }
    this.cooldowns.set(lockKey, now + 45_000);
    signal?.throwIfAborted();
    await this.publishToggle(env, parsed.data.flagKey, parsed.data.enabled, signal);
    return { status: 200 as const, updated: lockKey };
  }
}
