```ts
export class SerializedWallet {
  private balanceCents: number;
  private tail: Promise<void> = Promise.resolve();

  constructor(initialCents: number,
              private ledgerHook: (remaining: number) => Promise<void>) {
    this.balanceCents = initialCents;
  }

  withdraw(cents: number): Promise<boolean> {
    const op = this.tail.then(async () => {
      if (cents <= 0 || this.balanceCents < cents) {
        return false;
      }
      const next = this.balanceCents - cents;
      await this.ledgerHook(next);
      this.balanceCents = next;
      return true;
    });
    this.tail = op.then(() => undefined, () => undefined);
    return op;
  }

  balance(): number {
    return this.balanceCents;
  }
}
