Write a Rust `#[cfg(test)] mod tests` round-trip and corruption-rejection suite for the binary TLV + Fletcher-16 frame codec below:
```rust
#[derive(Debug, PartialEq, Eq)]
pub enum TlvError {
    ShortFrame,
    LengthMismatch,
    BadChecksum,
}

fn fletcher16(data: &[u8]) -> u16 {
    let (mut s1, mut s2) = (0_u16, 0_u16);
    for &b in data {
        s1 = (s1 + u16::from(b)) % 255;
        s2 = (s2 + s1) % 255;
    }
    (s2 << 8) | s1
}

pub fn encode_tlv(tag: u8, value: &[u8]) -> Result<Vec<u8>, TlvError> {
    let len = u16::try_from(value.len()).map_err(|_| TlvError::LengthMismatch)?;
    let mut buf = Vec::with_capacity(5 + value.len());
    buf.push(tag);
    buf.extend_from_slice(&len.to_be_bytes());
    buf.extend_from_slice(value);
    let sum = fletcher16(&buf);
    buf.extend_from_slice(&sum.to_be_bytes());
    Ok(buf)
}

pub fn decode_tlv(raw: &[u8]) -> Result<(u8, Vec<u8>), TlvError> {
    if raw.len() < 5 {
        return Err(TlvError::ShortFrame);
    }
    let tag = raw[0];
    let len = u16::from_be_bytes([raw[1], raw[2]]) as usize;
    if raw.len() != 5 + len {
        return Err(TlvError::LengthMismatch);
    }
    let (body, csum_bytes) = raw.split_at(3 + len);
    let got = u16::from_be_bytes([csum_bytes[0], csum_bytes[1]]);
    if fletcher16(body) != got {
        return Err(TlvError::BadChecksum);
    }
    Ok((tag, body[3..].to_vec()))
}
