Write a Go test suite for `credits/mint_gate.go` verifying first-call `201` execution, cached `mintID` replay on duplicate `Idempotency-Key` retries without double-minting, and `409 Conflict` (`ErrIdemMismatch`) when `accountID` or `units` mutates:
```go
package credits

import (
	"crypto/sha256"
	"errors"
	"fmt"
	"net/http"
	"sync"
)

var ErrIdemMismatch = errors.New("idempotency key payload mismatch")

type record struct {
	digest [32]byte
	mintID string
}

type MintGate struct {
	mu     sync.Mutex
	seen   map[string]record
	mintFn func(accountID string, units uint64) string
}

func NewMintGate(fn func(string, uint64) string) *MintGate {
	return &MintGate{seen: make(map[string]record), mintFn: fn}
}

func (g *MintGate) Mint(idemKey, accountID string, units uint64) (int, string, error) {
	if idemKey == "" {
		return http.StatusBadRequest, "", errors.New("empty idemKey")
	}
	sum := sha256.Sum256([]byte(fmt.Sprintf("%s:%d", accountID, units)))
	g.mu.Lock()
	defer g.mu.Unlock()
	if r, ok := g.seen[idemKey]; ok {
		if r.digest != sum {
			return http.StatusConflict, "", ErrIdemMismatch
		}
		return http.StatusOK, r.mintID, nil
	}
	id := g.mintFn(accountID, units)
	g.seen[idemKey] = record{digest: sum, mintID: id}
	return http.StatusCreated, id, nil
}
