Write a `pytest` suite for `clients/clearing_house.py` simulating `503` -> `429` (`Retry-After: 5`) -> `200`, verifying backoff delays on `GET` and keyed `POST`, while proving unkeyed `POST` never retries on `TimeoutError` or `503`:
```python
from typing import Callable

class ClearingClient:
    def __init__(
        self,
        transport: Callable[[str, str, dict[str, str]], tuple[int, dict[str, str], str]],
        sleep_fn: Callable[[float], None],
    ) -> None:
        self._transport = transport
        self._sleep = sleep_fn

    def send(self, method: str, path: str, idem_key: str | None = None) -> tuple[int, str]:
        verb = method.upper()
        safe = verb == 'GET' or bool(idem_key and idem_key.strip())
        max_attempts = 3 if safe else 1
        hdrs = {'Idempotency-Key': idem_key.strip()} if idem_key and idem_key.strip() else {}

        for attempt in range(1, max_attempts + 1):
            try:
                status, resp_hdrs, body = self._transport(verb, path, dict(hdrs))
            except TimeoutError:
                if attempt == max_attempts:
                    raise
                self._sleep(0.5 * attempt)
                continue

            if (status < 500 and status != 429) or attempt == max_attempts:
                return status, body
            ra = resp_hdrs.get('Retry-After', '')
            wait = float(ra) if ra.isdigit() and int(ra) > 0 else 0.5 * attempt
            self._sleep(wait)
        raise RuntimeError('unreachable')
