Write a `pytest.mark.parametrize` boundary and regression suite for `webauthn/challenge_verifier.py` below:
```python
import base64

MIN_CHALLENGE_BYTES = 16
MAX_CHALLENGE_BYTES = 64

class CeremonyError(ValueError):
    pass

def verify_webauthn_challenge(
    rp_id: str,
    expected_rp_id: str,
    challenge_b64url: str,
    sign_count: int,
    prev_sign_count: int,
    issued_at: int,
    now_ts: int,
    ttl_sec: int = 120,
) -> bytes:
    if not rp_id or rp_id != rp_id.lower() or not rp_id.isascii() or rp_id != expected_rp_id:
        raise CeremonyError('rp_id mismatch or non-canonical')
    if '=' in challenge_b64url or '+' in challenge_b64url or '/' in challenge_b64url:
        raise CeremonyError('non-base64url characters')
    pad = '=' * (-len(challenge_b64url) % 4)
    try:
        raw = base64.urlsafe_b64decode(challenge_b64url + pad)
    except Exception as exc:
        raise CeremonyError('malformed base64url') from exc
    if not (MIN_CHALLENGE_BYTES <= len(raw) <= MAX_CHALLENGE_BYTES):
        raise CeremonyError('challenge length out of bounds')
    if isinstance(sign_count, bool) or isinstance(prev_sign_count, bool):
        raise CeremonyError('boolean counter forbidden')
    if sign_count < 0 or prev_sign_count < 0:
        raise CeremonyError('negative sign_count')
    if not (sign_count == 0 and prev_sign_count == 0) and sign_count <= prev_sign_count:
        raise CeremonyError('cloned authenticator counter regression')
    if now_ts < issued_at or (now_ts - issued_at) >= ttl_sec:
        raise CeremonyError('challenge outside validity window')
    return raw
