Write idiomatic table-driven Go tests (`t.Run`) for `gossip/block_proposal.go` verifying HTTP status codes, the 3072-byte `MaxBytesReader` cap, `bootstrapValidators` slice non-aliasing, and `errors.Is` wrapping on `ErrMalformedParentHash`:
```go
package gossip

import (
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
)

const MaxProposalBytes = 3072

var ErrMalformedParentHash = errors.New("parent_hash must be 64 lowercase hex chars")

type BlockProposal struct {
	Height     uint64   `json:"height"`
	ParentHash string   `json:"parent_hash"`
	Signers    []string `json:"signers"`
}

func DecodeBlockProposal(w http.ResponseWriter, r *http.Request, bootstrapValidators []string) ([]string, int, error) {
	if r.Method != http.MethodPost {
		return nil, http.StatusMethodNotAllowed, fmt.Errorf("method %s rejected", r.Method)
	}
	r.Body = http.MaxBytesReader(w, r.Body, MaxProposalBytes)
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	var bp BlockProposal
	if err := dec.Decode(&bp); err != nil {
		var maxErr *http.MaxBytesError
		if errors.As(err, &maxErr) {
			return nil, http.StatusRequestEntityTooLarge, fmt.Errorf("proposal body: %w", err)
		}
		return nil, http.StatusBadRequest, fmt.Errorf("proposal json: %w", err)
	}
	if bp.Height == 0 {
		return nil, http.StatusUnprocessableEntity, errors.New("genesis height cannot be proposed")
	}
	if len(bp.ParentHash) != 64 {
		return nil, http.StatusUnprocessableEntity, fmt.Errorf("hash len %d: %w", len(bp.ParentHash), ErrMalformedParentHash)
	}
	if _, err := hex.DecodeString(bp.ParentHash); err != nil {
		return nil, http.StatusUnprocessableEntity, fmt.Errorf("hex decode: %w", ErrMalformedParentHash)
	}
	quorum := make([]string, 0, len(bootstrapValidators)+len(bp.Signers))
	quorum = append(quorum, bootstrapValidators...)
	quorum = append(quorum, bp.Signers...)
	return quorum, http.StatusAccepted, nil
}
