}

pub struct RateValve {
    refill_per_sec: u64,
    tokens: u64,
    mode: GateMode,
    drops: [u32; 4],
    cursor: usize,
}

impl FromStr for RateValve {
    type Err = ValveErr;
    fn from_str(spec: &str) -> Result<Self, Self::Err> {
        let (r_part, b_part) = spec.split_once('@').ok_or(ValveErr::BadSpec)?;
        let refill: u64 = r_part.parse().map_err(|_| ValveErr::BadSpec)?;
        let burst: u64 = b_part.parse().map_err(|_| ValveErr::BadSpec)?;
        if refill == 0 || burst < refill {
            return Err(ValveErr::BadSpec);
        }
        Ok(Self { refill_per_sec: refill, tokens: burst, mode: GateMode::Warmup, drops: [0; 4], cursor: 0 })
    }
}

impl RateValve {
    pub fn set_mode(&mut self, next: GateMode) -> Result<(), ValveErr> {
        let ok = matches!(
            (self.mode, next),
            (GateMode::Warmup, GateMode::Enforcing)
                | (GateMode::Enforcing, GateMode::Shedding)
                | (GateMode::Shedding, GateMode::Enforcing)
        );
        if !ok {
            return Err(ValveErr::IllegalMode(self.mode, next));
        }
        self.mode = next;
        Ok(())
    }

    pub fn credit_elapsed(&mut self, elapsed_secs: u64) -> Option<u64> {
        let added = self.refill_per_sec.checked_mul(elapsed_secs)?;
        let updated = self.tokens.checked_add(added)?;
        self.tokens = updated;
        Some(updated)
    }

    pub fn record_drop_batch(&mut self, rejected: u32) -> Result<[u32; 4], ValveErr> {
        if self.mode != GateMode::Enforcing {
            return Err(ValveErr::NotEnforcing);
        }
        self.drops[self.cursor % 4] = rejected;
        self.cursor = self.cursor.wrapping_add(1);
        Ok(self.drops)
    }
}
