Write a Vitest security regression suite for `src/jwt/verifyAssertion.ts` covering pinned `ES256` algorithm enforcement (`none`/`HS256` rejected), `nbf`/`exp` clock-skew leeway via `vi.useFakeTimers()`, strict Zod rejection of injected claims, and `AbortSignal` cancellation:
```ts
import { z } from 'zod';

const HeaderSchema = z.object({
  alg: z.literal('ES256'),
  kid: z.string().min(4).max(64),
}).strict();

const PayloadSchema = z.object({
  sub: z.string().min(1),
  tenantId: z.string().min(1),
  nbf: z.number().int(),
  exp: z.number().int(),
}).strict();

export class AssertionVerifier {
  constructor(
    private verifySig: (kid: string, signingInput: string, sigB64: string, signal?: AbortSignal) => Promise<boolean>,
    private skewSec = 5,
  ) {}

  async verify(token: string, signal?: AbortSignal) {
    const parts = token.split('.');
    if (parts.length !== 3 || parts.some((p) => p.length === 0)) {
      return { ok: false as const, code: 'malformed_jws' };
    }
    let hdrRaw: unknown;
    let payRaw: unknown;
    try {
      hdrRaw = JSON.parse(Buffer.from(parts[0], 'base64url').toString('utf8'));
      payRaw = JSON.parse(Buffer.from(parts[1], 'base64url').toString('utf8'));
    } catch {
      return { ok: false as const, code: 'invalid_json' };
    }
    const hdr = HeaderSchema.safeParse(hdrRaw);
    if (!hdr.success) return { ok: false as const, code: 'bad_header' };
    const pay = PayloadSchema.safeParse(payRaw);
    if (!pay.success) return { ok: false as const, code: 'bad_claims' };

    const nowSec = Math.floor(Date.now() / 1000);
    if (nowSec + this.skewSec < pay.data.nbf) return { ok: false as const, code: 'immature_token' };
    if (nowSec - this.skewSec >= pay.data.exp) return { ok: false as const, code: 'expired_token' };

    signal?.throwIfAborted();
    const valid = await this.verifySig(hdr.data.kid, `${parts[0]}.${parts[1]}`, parts[2], signal);
    if (!valid) return { ok: false as const, code: 'bad_signature' };
    return { ok: true as const, claims: pay.data };
  }
}
