Write a Go concurrency stress test (`sync.WaitGroup` + barrier channel, clean under `go test -race`) proving `TenantRateBucket.Take` never over-allocates tokens beyond `capacity + refilled` and never drops below zero when 64 goroutines race simultaneously:
```go
package ratelimit

import "sync"

type TenantRateBucket struct {
	mu       sync.Mutex
	capacity int64
	tokens   int64
}

func NewTenantRateBucket(capacity int64) *TenantRateBucket {
	return &TenantRateBucket{capacity: capacity, tokens: capacity}
}

func (b *TenantRateBucket) Take(cost int64) bool {
	if cost <= 0 {
		return false
	}
	b.mu.Lock()
	defer b.mu.Unlock()
	if b.tokens < cost {
		return false
	}
	b.tokens -= cost
	return true
}

func (b *TenantRateBucket) Refill(amount int64) int64 {
	if amount <= 0 {
		return 0
	}
	b.mu.Lock()
	defer b.mu.Unlock()
	space := b.capacity - b.tokens
	if amount > space {
		amount = space
	}
	b.tokens += amount
	return amount
}

func (b *TenantRateBucket) Available() int64 {
	b.mu.Lock()
	defer b.mu.Unlock()
	return b.tokens
}
