func TestTenantRateBucketConcurrencyConservation(t *testing.T) {
	const initialCap int64 = 500
	const takers = 64
	const attemptsPerTaker = 40
	const cost int64 = 3

	bucket := NewTenantRateBucket(initialCap)
	start := make(chan struct{})
	var wg sync.WaitGroup
	var consumed atomic.Int64
	var credited atomic.Int64

	for i := 0; i < takers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			<-start
			for j := 0; j < attemptsPerTaker; j++ {
				if bucket.Take(cost) {
					consumed.Add(cost)
				}
			}
		}()
	}

	for r := 0; r < 8; r++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			<-start
			for k := 0; k < 25; k++ {
				added := bucket.Refill(10)
				credited.Add(added)
				avail := bucket.Available()
				if avail < 0 || avail > initialCap {
					t.Errorf("bucket invariant broken: available=%d", avail)
				}
			}
		}()
	}

	close(start)
	wg.Wait()

	if bucket.Take(0) || bucket.Take(-5) {
		t.Fatalf("non-positive Take must return false")
	}

	rem := bucket.Available()
	if rem < 0 || rem > initialCap {
		t.Fatalf("final remaining %d outside [0, %d]", rem, initialCap)
