Write a Rust `#[cfg(test)] mod tests` round-trip and malformed-frame rejection suite for the binary Merkle proof wire codec below:
```rust
#[derive(Debug, PartialEq, Eq)]
pub enum ProofWireErr {
    BadMagic,
    DepthExceeded,
    LengthMismatch,
    ChecksumMismatch,
}

const MAGIC: [u8; 2] = [0x4D, 0x50];
const MAX_DEPTH: usize = 32;

fn fold_tag(bytes: &[u8]) -> u8 {
    bytes.iter().fold(0xA7_u8, |acc, &b| acc.wrapping_add(b) ^ 0x3C)
}

pub fn encode_merkle_proof(leaf_idx: u32, siblings: &[[u8; 32]]) -> Result<Vec<u8>, ProofWireErr> {
    if siblings.len() > MAX_DEPTH {
        return Err(ProofWireErr::DepthExceeded);
    }
    let mut out = Vec::with_capacity(7 + siblings.len() * 32 + 1);
    out.extend_from_slice(&MAGIC);
    out.extend_from_slice(&leaf_idx.to_be_bytes());
    out.push(siblings.len() as u8);
    for h in siblings {
        out.extend_from_slice(h);
    }
    let tag = fold_tag(&out);
    out.push(tag);
    Ok(out)
}

pub fn decode_merkle_proof(frame: &[u8]) -> Result<(u32, Vec<[u8; 32]>), ProofWireErr> {
    if frame.len() < 8 {
        return Err(ProofWireErr::LengthMismatch);
    }
    if frame[0..2] != MAGIC {
        return Err(ProofWireErr::BadMagic);
    }
    let leaf_idx = u32::from_be_bytes([frame[2], frame[3], frame[4], frame[5]]);
    let depth = frame[6] as usize;
    if depth > MAX_DEPTH {
        return Err(ProofWireErr::DepthExceeded);
    }
    let expected = 7 + depth * 32 + 1;
    if frame.len() != expected {
        return Err(ProofWireErr::LengthMismatch);
    }
    let (body, tail) = frame.split_at(expected - 1);
    if fold_tag(body) != tail[0] {
        return Err(ProofWireErr::ChecksumMismatch);
    }
    let mut siblings = Vec::with_capacity(depth);
    for chunk in body[7..].chunks_exact(32) {
        let mut arr = [0_u8; 32];
        arr.copy_from_slice(chunk);
        siblings.push(arr);
    }
    Ok((leaf_idx, siblings))
}
