```python
from dataclasses import dataclass
from typing import Callable

@dataclass(frozen=True)
class JwtClaims:
    sub: str
    tenant_id: str
    role: str
    nbf_ts: int
    exp_ts: int

def freeze_ledger_account(
    claims: JwtClaims | None,
    target_tenant: str,
    account_id: str,
    now_ts: int,
    freeze_sink: Callable[[str, str, str], str],
) -> tuple[int, dict]:
    if claims is None or not claims.sub.strip():
        return 401, {'error': 'missing_principal'}
    if now_ts < claims.nbf_ts:
        return 401, {'error': 'token_not_yet_valid'}
    if now_ts >= claims.exp_ts:
        return 401, {'error': 'token_expired'}
    if claims.tenant_id != target_tenant:
        return 403, {'error': 'tenant_boundary_violation'}
    if claims.role != 'compliance_officer':
        return 403, {'error': 'role_denied'}
    hold_ref = freeze_sink(target_tenant, account_id, claims.sub)
    return 200, {'status': 'frozen', 'hold_ref': hold_ref}
