Write a Vitest suite for `src/ledger/postTransfer.ts` verifying tenant-scoped `Idempotency-Key` isolation (same key across distinct tenants does not collide), cached `200` replay on retries without double-posting, and `409` rejection when retry parameters mutate:
```ts
import { createHash } from 'node:crypto';

export interface TransferSpec {
  fromAccount: string;
  toAccount: string;
  minorUnits: number;
}

export class TenantIdempotentLedger {
  private cache = new Map<string, { digest: string; journalId: string }>();

  constructor(private commitFn: (tenantId: string, spec: TransferSpec) => Promise<string>) {}

  async post(tenantId: string, idemKey: string, spec: TransferSpec) {
    const cleanKey = idemKey.trim();
    if (!tenantId || cleanKey.length < 6) {
      return { status: 400 as const, error: 'invalid_key_or_tenant' };
    }
    const digest = createHash('sha256')
      .update(`${spec.fromAccount}->${spec.toAccount}:${spec.minorUnits}`)
      .digest('hex');
    const composite = `${tenantId}::${cleanKey}`;
    const hit = this.cache.get(composite);
    if (hit) {
      if (hit.digest !== digest) {
        return { status: 409 as const, error: 'payload_conflict' };
      }
      return { status: 200 as const, journalId: hit.journalId, replayed: true };
    }
    const journalId = await this.commitFn(tenantId, spec);
    this.cache.set(composite, { digest, journalId });
    return { status: 201 as const, journalId, replayed: false };
  }
}
