DUST_SATS = 546
MAX_SUPPLY_SATS = 2_100_000_000_000_000
MAX_BLOCK_HEIGHT = 499_999_999

class UtxoSpendError(ValueError):
    pass

def validate_timelocked_utxo(
    txid_hex: str,
    vout_index: int,
    satoshis: int,
    unlock_height: int,
    chain_tip_height: int,
) -> tuple[str, int, int]:
    if len(txid_hex) != 64 or txid_hex != txid_hex.lower():
        raise UtxoSpendError('txid must be 64 lowercase hex chars')
    try:
        bytes.fromhex(txid_hex)
    except ValueError as exc:
        raise UtxoSpendError('invalid txid hex') from exc
    if any(isinstance(x, bool) for x in (vout_index, satoshis, unlock_height, chain_tip_height)):
        raise UtxoSpendError('boolean integer forbidden')
    if not (0 <= vout_index <= 255):
        raise UtxoSpendError('vout_index out of bounds')
    if not (DUST_SATS <= satoshis <= MAX_SUPPLY_SATS):
        raise UtxoSpendError('satoshis outside dust/supply bounds')
    if not (0 <= unlock_height <= MAX_BLOCK_HEIGHT):
        raise UtxoSpendError('unlock_height outside block-height domain')
    if chain_tip_height < unlock_height:
        raise UtxoSpendError('utxo still timelocked')
    return txid_hex, vout_index, satoshis
