Write idiomatic table-driven Go tests (`t.Run`) for `webauthn/cose_policy.go` verifying HTTP status codes, the 1024-byte `MaxBytesReader` limit, `defaultAlgs` slice non-aliasing, and `errors.Is` wrapping on `ErrDisallowedCOSEAlg`:
```go
package webauthn

import (
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
)

const MaxCeremonyBytes = 1024

var ErrDisallowedCOSEAlg = errors.New("disallowed COSE algorithm identifier")

type CeremonySpec struct {
	RPID      string `json:"rp_id"`
	ExtraAlgs []int  `json:"extra_algs"`
}

func ParseCeremonyAlgs(w http.ResponseWriter, r *http.Request, defaultAlgs []int) ([]int, int, error) {
	if r.Method != http.MethodPost {
		return nil, http.StatusMethodNotAllowed, fmt.Errorf("method %s not allowed", r.Method)
	}
	r.Body = http.MaxBytesReader(w, r.Body, MaxCeremonyBytes)
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	var spec CeremonySpec
	if err := dec.Decode(&spec); err != nil {
		var maxErr *http.MaxBytesError
		if errors.As(err, &maxErr) {
			return nil, http.StatusRequestEntityTooLarge, fmt.Errorf("ceremony body: %w", err)
		}
		return nil, http.StatusBadRequest, fmt.Errorf("ceremony json: %w", err)
	}
	if spec.RPID == "" {
		return nil, http.StatusBadRequest, errors.New("empty rp_id")
	}
	for _, alg := range spec.ExtraAlgs {
		if alg != -7 && alg != -8 && alg != -257 {
			return nil, http.StatusUnprocessableEntity, fmt.Errorf("alg %d: %w", alg, ErrDisallowedCOSEAlg)
		}
	}
	out := make([]int, 0, len(defaultAlgs)+len(spec.ExtraAlgs))
	out = append(out, defaultAlgs...)
	out = append(out, spec.ExtraAlgs...)
	return out, http.StatusOK, nil
}
