Write a Rust `#[cfg(test)] mod tests` suite for `SlashingTracker` verifying `checked_add` penalty overflow returning `None`, `FromStr` malformed input rejection, `ValidatorState` invalid state transitions, and stack-only `[u64; 4]` fault-epoch ring behavior:
```rust
use std::str::FromStr;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ValidatorState {
    Bonded,
    Jailed,
    Unbonding,
    Exited,
}

#[derive(Debug, PartialEq, Eq)]
pub enum SlashErr {
    BadPolicy,
    IllegalState(ValidatorState, ValidatorState),
    ValidatorInactive,
}

pub struct SlashingTracker {
    max_slash_gwei: u64,
    slashed_gwei: u64,
    state: ValidatorState,
    fault_epochs: [u64; 4],
    head: usize,
}

impl FromStr for SlashingTracker {
    type Err = SlashErr;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let val = s.strip_prefix("cap_gwei=").ok_or(SlashErr::BadPolicy)?;
        let cap: u64 = val.parse().map_err(|_| SlashErr::BadPolicy)?;
        if cap == 0 {
            return Err(SlashErr::BadPolicy);
        }
        Ok(Self { max_slash_gwei: cap, slashed_gwei: 0, state: ValidatorState::Bonded, fault_epochs: [0; 4], head: 0 })
    }
}

impl SlashingTracker {
    pub fn transition(&mut self, next: ValidatorState) -> Result<(), SlashErr> {
        let ok = matches!(
            (self.state, next),
            (ValidatorState::Bonded, ValidatorState::Jailed)
                | (ValidatorState::Bonded, ValidatorState::Unbonding)
                | (ValidatorState::Jailed, ValidatorState::Unbonding)
                | (ValidatorState::Unbonding, ValidatorState::Exited)
        );
        if !ok {
            return Err(SlashErr::IllegalState(self.state, next));
        }
        self.state = next;
        Ok(())
    }

    pub fn apply_penalty(&mut self, epoch: u64, gwei: u64) -> Result<Option<u64>, SlashErr> {
        if matches!(self.state, ValidatorState::Exited) {
            return Err(SlashErr::ValidatorInactive);
        }
        let Some(total) = self.slashed_gwei.checked_add(gwei) else {
            return Ok(None);
        };
        if total > self.max_slash_gwei {
            return Ok(None);
        }
        self.slashed_gwei = total;
        self.fault_epochs[self.head % 4] = epoch;
        self.head = self.head.wrapping_add(1);
        Ok(Some(total))
    }
}
