Write a Vitest security regression suite for `src/ratelimit/gcraGateway.ts` covering strict Zod rejection of injected `unlimitedTier` fields, `Origin` checks, GCRA burst/TAT recovery via `vi.useFakeTimers()`, and `AbortSignal` cancellation:
```ts
import { z } from 'zod';

const RpcEnvelopeSchema = z.object({
  method: z.enum(['eth_blockNumber', 'eth_getBalance']),
  weight: z.number().int().min(1).max(5),
}).strict();

const DAPP_ORIGINS = new Set(['https://wallet.chain.internal']);

export class GcraRpcGateway {
  private tatMs = new Map<string, number>();

  constructor(
    private intervalMs: number,
    private burstToleranceMs: number,
    private forwardRpc: (tenant: string, method: string, sig?: AbortSignal) => Promise<string>,
  ) {}

  async handle(tenant: string, origin: string | undefined, body: unknown, signal?: AbortSignal) {
    if (!origin || !DAPP_ORIGINS.has(origin)) {
      return { status: 403 as const, error: 'origin_denied' };
    }
    const parsed = RpcEnvelopeSchema.safeParse(body);
    if (!parsed.success) {
      return { status: 400 as const, error: 'invalid_rpc_envelope' };
    }
    const now = Date.now();
    const increment = parsed.data.weight * this.intervalMs;
    const prevTat = this.tatMs.get(tenant) ?? now;
    const nextTat = Math.max(now, prevTat) + increment;
    if (nextTat - now > this.burstToleranceMs + increment) {
      return { status: 429 as const, retryAfterMs: nextTat - now - (this.burstToleranceMs + increment) };
    }
    this.tatMs.set(tenant, nextTat);
    signal?.throwIfAborted();
    const result = await this.forwardRpc(tenant, parsed.data.method, signal);
    return { status: 200 as const, result };
  }
}
