Write a multi-thread Rust concurrency stress test using `std::sync::Barrier` proving `NonceSequencer::claim_batch` never assigns overlapping `[start, end)` ledger nonces or exceeds `epoch_ceiling` across 16 racing threads:
```rust
use std::sync::atomic::{AtomicU64, Ordering};

pub struct NonceSequencer {
    next: AtomicU64,
    epoch_ceiling: u64,
}

impl NonceSequencer {
    pub const fn new(start: u64, epoch_ceiling: u64) -> Self {
        Self { next: AtomicU64::new(start), epoch_ceiling }
    }

    pub fn claim_batch(&self, count: u64) -> Option<(u64, u64)> {
        if count == 0 {
            return None;
        }
        let mut prev_val = 0;
        self.next
            .fetch_update(Ordering::AcqRel, Ordering::Acquire, |cur| {
                let end = cur.checked_add(count)?;
                if end > self.epoch_ceiling {
                    return None;
                }
                prev_val = cur;
                Some(end)
            })
            .ok()
            .map(|start| (start, start + count))
    }

    pub fn cursor(&self) -> u64 {
        self.next.load(Ordering::Acquire)
    }
}
