    use std::collections::HashSet;
    use std::sync::{Arc, Barrier, Mutex};
    use std::thread;

    #[test]
    fn sixteen_threads_claim_disjoint_nonces_within_ceiling() {
        const START: u64 = 100;
        const CEILING: u64 = 605;
        const THREADS: usize = 16;

        let seq = Arc::new(NonceSequencer::new(START, CEILING));
        let gate = Arc::new(Barrier::new(THREADS));
        let claimed = Arc::new(Mutex::new(Vec::<(u64, u64)>::new()));

        let mut handles = Vec::with_capacity(THREADS);
        for tid in 0..THREADS {
            let seq = Arc::clone(&seq);
            let gate = Arc::clone(&gate);
            let claimed = Arc::clone(&claimed);
            handles.push(thread::spawn(move || {
                let step = if tid % 2 == 0 { 3_u64 } else { 5_u64 };
                gate.wait();
                let mut local = Vec::new();
                for _ in 0..40 {
                    if let Some(range) = seq.claim_batch(step) {
                        local.push(range);
                    }
                }
                claimed.lock().unwrap().extend(local);
            }));
        }

        for h in handles {
            h.join().unwrap();
        }

        assert_eq!(seq.claim_batch(0), None);
        assert!(seq.cursor() <= CEILING);

        let mut seen = HashSet::new();
        for &(lo, hi) in claimed.lock().unwrap().iter() {
            assert!(lo >= START && hi <= CEILING && lo < hi);
