import struct

class CanonicalCborError(ValueError):
    pass

def _crc16_ccitt(data: bytes) -> int:
    crc = 0xFFFF
    for b in data:
        crc ^= b << 8
        for _ in range(8):
            crc = ((crc << 1) ^ 0x1021) & 0xFFFF if (crc & 0x8000) else (crc << 1) & 0xFFFF
    return crc

def encode_cbor_frame(payload: bytes) -> bytes:
    n = len(payload)
    if n < 24:
        hdr = bytes([0x40 | n])
    elif n <= 0xFF:
        hdr = bytes([0x58, n])
    elif n <= 0xFFFF:
        hdr = struct.pack('>BH', 0x59, n)
    else:
        raise CanonicalCborError('payload exceeds 65535 bytes')
    body = hdr + payload
    return body + struct.pack('>H', _crc16_ccitt(body))

def decode_cbor_frame(raw: bytes) -> bytes:
    if len(raw) < 3:
        raise CanonicalCborError('truncated cbor frame')
    body, crc_raw = raw[:-2], raw[-2:]
    if _crc16_ccitt(body) != struct.unpack('>H', crc_raw)[0]:
        raise CanonicalCborError('crc16 mismatch')
    lead = body[0]
    if (lead >> 5) != 2:
        raise CanonicalCborError('expected major type 2 bstr')
    info = lead & 0x1F
    if info < 24:
        plen, offset = info, 1
    elif info == 24:
        if len(body) < 2 or body[1] < 24:
            raise CanonicalCborError('non-canonical 1-byte length')
        plen, offset = body[1], 2
    elif info == 25:
        if len(body) < 3:
            raise CanonicalCborError('truncated 2-byte length')
        (plen,) = struct.unpack('>H', body[1:3])
        if plen <= 0xFF:
            raise CanonicalCborError('non-canonical 2-byte length')
        offset = 3
    else:
        raise CanonicalCborError('unsupported additional info')
    if len(body) - offset != plen:
        raise CanonicalCborError('declared length mismatch')
    return body[offset:]
```

