type VerifiedClaims struct {
	Alg       string
	Sub       string
	TenantID  string
	Role      string
	NotBefore time.Time
	ExpiresAt time.Time
}

func PublishTenantKey(c *VerifiedClaims, targetTenant, kid string, now time.Time, publish func(string, string) error) int {
