Write a `pytest` suite for `ledger/settlement_batch.py` verifying cached `200` replay on duplicate `(tenant_id, idem_key)` submissions, single `settle_fn` execution, cross-tenant key isolation, and `409` conflict when leg order or amounts mutate:
```python
import hashlib
import json
from typing import Callable

class BatchConflictError(Exception):
    status_code = 409

class SettlementBatchCoordinator:
    def __init__(self, settle_fn: Callable[[str, list[tuple[str, int]]], str]) -> None:
        self._settle_fn = settle_fn
        self._store: dict[tuple[str, str], tuple[str, dict]] = {}

    def submit_batch(
        self,
        tenant_id: str,
        idem_key: str,
        legs: list[tuple[str, int]],
    ) -> tuple[int, dict]:
        clean_key = idem_key.strip()
        if not tenant_id or len(clean_key) < 8 or not legs:
            raise ValueError('invalid batch request')
        payload_json = json.dumps([[acct, amt] for acct, amt in legs], separators=(',', ':'))
        digest = hashlib.sha256(payload_json.encode('utf-8')).hexdigest()
        slot = (tenant_id, clean_key)
        if slot in self._store:
            saved_digest, cached = self._store[slot]
            if saved_digest != digest:
                raise BatchConflictError('batch legs mutated for existing idempotency key')
            return 200, dict(cached)
        batch_id = self._settle_fn(tenant_id, list(legs))
        resp = {'batch_id': batch_id, 'leg_count': len(legs)}
        self._store[slot] = (digest, resp)
        return 201, dict(resp)
```

Write a Vitest suite for `src/net/jwksFetcher.ts` using `vi.useFakeTimers()` verifying per-attempt `AbortController` timeouts, `2000ms` exponential backoff cap, `Retry-After` precedence on `429`, immediate halt on `404`, and caller `parentSignal` cancellation during backoff sleep:
```ts
export async function fetchJwksWithBackoff(
  url: string,
  transport: (url: string, signal: AbortSignal) => Promise<Response>,
  opts: { perTryMs: number; maxAttempts: number; parentSignal?: AbortSignal },
): Promise<Response> {
  for (let attempt = 1; attempt <= opts.maxAttempts; attempt++) {
    opts.parentSignal?.throwIfAborted();
    const attemptCtrl = new AbortController();
    const onParentAbort = () => attemptCtrl.abort();
    opts.parentSignal?.addEventListener('abort', onParentAbort, { once: true });
    const timer = setTimeout(() => attemptCtrl.abort(), opts.perTryMs);

    try {
      const resp = await transport(url, attemptCtrl.signal);
      if ((resp.status < 500 && resp.status !== 429) || attempt === opts.maxAttempts) {
        return resp;
      }
      const ra = Number.parseInt(resp.headers.get('Retry-After') ?? '', 10);
      const waitMs = Number.isFinite(ra) && ra > 0 ? ra * 1000 : Math.min(2000, 500 * 2 ** (attempt - 1));
      await sleepWithSignal(waitMs, opts.parentSignal);
    } catch (err) {
      opts.parentSignal?.throwIfAborted();
      if (attempt === opts.maxAttempts) throw err;
      const waitMs = Math.min(2000, 500 * 2 ** (attempt - 1));
      await sleepWithSignal(waitMs, opts.parentSignal);
    } finally {
      clearTimeout(timer);
      opts.parentSignal?.removeEventListener('abort', onParentAbort);
    }
  }
  throw new Error('exhausted');
}

function sleepWithSignal(ms: number, signal?: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    signal?.throwIfAborted();
    const t = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);
    const onAbort = () => {
      clearTimeout(t);
      reject(signal?.reason ?? new DOMException('Aborted', 'AbortError'));
    };
    signal?.addEventListener('abort', onAbort, { once: true });
  });
}
