Write a `pytest.mark.parametrize` boundary and security regression suite for RFC 9449 DPoP proof claim validation in `jwt/dpop_proof_gate.py`:
```python
class DPoPProofError(ValueError):
    pass

def validate_dpop_proof(
    jti: str,
    htm: str,
    expected_htm: str,
    htu: str,
    expected_htu: str,
    iat_ts: int,
    now_ts: int,
    max_skew_sec: int = 5,
    max_age_sec: int = 60,
) -> str:
    if not (12 <= len(jti) <= 128) or not jti.isascii() or any(c.isspace() for c in jti):
        raise DPoPProofError('invalid jti nonce')
    if htm != expected_htm or htm not in {'GET', 'POST', 'PUT', 'DELETE'}:
        raise DPoPProofError('htm method mismatch')
    if not htu.startswith('https://') or '?' in htu or '#' in htu or htu != expected_htu:
        raise DPoPProofError('invalid or mismatched htu')
    if isinstance(iat_ts, bool) or isinstance(now_ts, bool):
        raise DPoPProofError('boolean timestamp forbidden')
    if iat_ts > now_ts + max_skew_sec:
        raise DPoPProofError('proof issued in future beyond skew')
    if now_ts - iat_ts > max_age_sec:
        raise DPoPProofError('stale dpop proof')
    return jti
