Write idiomatic table-driven Go tests (`t.Run`) for `ratelimit/tier_override.go` checking HTTP status codes, the 1536-byte `MaxBytesReader` limit, `baseRoutes` slice non-aliasing, and `errors.Is` wrapping on `ErrBurstBelowRate`:
```go
package ratelimit

import (
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
)

const MaxTierBody = 1536

var ErrBurstBelowRate = errors.New("burst must be >= rps and positive")

type TierPatch struct {
	RPS    int64    `json:"rps"`
	Burst  int64    `json:"burst"`
	Routes []string `json:"routes"`
}

func ParseTierPatch(w http.ResponseWriter, r *http.Request, baseRoutes []string) ([]string, int, error) {
	if r.Method != http.MethodPut {
		return nil, http.StatusMethodNotAllowed, fmt.Errorf("method %s disallowed", r.Method)
	}
	r.Body = http.MaxBytesReader(w, r.Body, MaxTierBody)
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	var tp TierPatch
	if err := dec.Decode(&tp); err != nil {
		var maxErr *http.MaxBytesError
		if errors.As(err, &maxErr) {
			return nil, http.StatusRequestEntityTooLarge, fmt.Errorf("tier body: %w", err)
		}
		return nil, http.StatusBadRequest, fmt.Errorf("tier decode: %w", err)
	}
	if tp.RPS <= 0 || tp.Burst < tp.RPS {
		return nil, http.StatusUnprocessableEntity, fmt.Errorf("rps=%d burst=%d: %w", tp.RPS, tp.Burst, ErrBurstBelowRate)
	}
	out := make([]string, 0, len(baseRoutes)+len(tp.Routes))
	out = append(out, baseRoutes...)
	out = append(out, tp.Routes...)
	return out, http.StatusOK, nil
}
