Write a Rust `#[cfg(test)] mod tests` suite for `PaymentChannel` verifying `checked_sub`/`checked_add` balance conservation and `None` on underflow/overflow, `FromStr` malformed capacity rejection, `ChanPhase` invalid transitions, and stack-only `[u64; 4]` sequence checkpoints:
```rust
use std::str::FromStr;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ChanPhase {
    Opening,
    Open,
    Closing,
    Closed,
}

#[derive(Debug, PartialEq, Eq)]
pub enum ChanErr {
    BadInit,
    InvalidPhase(ChanPhase, ChanPhase),
    ChannelNotOpen,
}

pub struct PaymentChannel {
    local_sats: u64,
    remote_sats: u64,
    seq: u64,
    phase: ChanPhase,
    recent_seqs: [u64; 4],
    slot: usize,
}

impl FromStr for PaymentChannel {
    type Err = ChanErr;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let (l_s, r_s) = s.split_once(':').ok_or(ChanErr::BadInit)?;
        let l: u64 = l_s.parse().map_err(|_| ChanErr::BadInit)?;
        let r: u64 = r_s.parse().map_err(|_| ChanErr::BadInit)?;
        let cap = l.checked_add(r).ok_or(ChanErr::BadInit)?;
        if cap == 0 {
            return Err(ChanErr::BadInit);
        }
        Ok(Self { local_sats: l, remote_sats: r, seq: 0, phase: ChanPhase::Opening, recent_seqs: [0; 4], slot: 0 })
    }
}

impl PaymentChannel {
    pub fn set_phase(&mut self, next: ChanPhase) -> Result<(), ChanErr> {
        let ok = matches!(
            (self.phase, next),
            (ChanPhase::Opening, ChanPhase::Open)
                | (ChanPhase::Open, ChanPhase::Closing)
                | (ChanPhase::Closing, ChanPhase::Closed)
        );
        if !ok {
            return Err(ChanErr::InvalidPhase(self.phase, next));
        }
        self.phase = next;
        Ok(())
    }

    pub fn push_to_remote(&mut self, sats: u64) -> Result<Option<(u64, u64)>, ChanErr> {
        if self.phase != ChanPhase::Open {
            return Err(ChanErr::ChannelNotOpen);
        }
        if sats == 0 {
            return Ok(None);
        }
        let Some(next_local) = self.local_sats.checked_sub(sats) else {
            return Ok(None);
        };
        let Some(next_remote) = self.remote_sats.checked_add(sats) else {
            return Ok(None);
        };
        let Some(next_seq) = self.seq.checked_add(1) else {
            return Ok(None);
        };
        self.local_sats = next_local;
        self.remote_sats = next_remote;
        self.seq = next_seq;
        self.recent_seqs[self.slot % 4] = next_seq;
        self.slot = self.slot.wrapping_add(1);
        Ok(Some((self.local_sats, self.remote_sats)))
    }
}
