const ClientDataSchema = z.object({
  type: z.literal('webauthn.get'),
  challenge: z.string().min(16),
  origin: z.string().url(),
  crossOrigin: z.literal(false).optional(),
}).strict();

const RP_ORIGINS = new Set(['https://auth.vault.internal']);

export class WebAuthnAssertionGate {
  private challenges = new Map<string, number>();

  constructor(private verifyAuthSig: (credId: string, clientJson: string, sig?: AbortSignal) => Promise<boolean>) {}

  issueChallenge(nonce: string, ttlMs = 60_000): void {
    this.challenges.set(nonce, Date.now() + ttlMs);
