Write a multi-thread `pytest` stress test using `threading.Barrier` and `ThreadPoolExecutor` proving `BoundedStakePool` never exceeds `cap_units`, never underflows per-staker balances, and preserves `sum(balances) == total_staked` across 24 racing threads:
```python
import threading

class BoundedStakePool:
    def __init__(self, cap_units: int) -> None:
        self._lock = threading.Lock()
        self._cap = cap_units
        self._total = 0
        self._stakes: dict[str, int] = {}

    def delegate(self, staker: str, units: int) -> bool:
        if units <= 0:
            return False
        with self._lock:
            if self._total + units > self._cap:
                return False
            self._total += units
            self._stakes[staker] = self._stakes.get(staker, 0) + units
            return True

    def undelegate(self, staker: str, units: int) -> bool:
        if units <= 0:
            return False
        with self._lock:
            cur = self._stakes.get(staker, 0)
            if cur < units:
                return False
            self._stakes[staker] = cur - units
            self._total -= units
            return True

    def snapshot(self) -> tuple[int, dict[str, int]]:
        with self._lock:
            return self._total, dict(self._stakes)
```

Write a Go unit test suite for the ZigZag + LEB128 signed delta frame codec `framing/zigzag_frame.go` testing negative/zero/boundary `int64` round-trips and rejecting bad magic, `count > 32`, truncated varints, trailing bytes, and checksum bitflips:
```go
package framing

import "errors"

const (
	FrameMagic = 0xD7
	MaxDeltas  = 32
)

var (
	ErrBadFrame    = errors.New("malformed delta frame")
	ErrBadChecksum = errors.New("frame checksum mismatch")
)

func EncodeDeltaFrame(deltas []int64) ([]byte, error) {
	if len(deltas) > MaxDeltas {
		return nil, ErrBadFrame
	}
	out := make([]byte, 0, 2+len(deltas)*2+1)
	out = append(out, FrameMagic, byte(len(deltas)))
	for _, d := range deltas {
		zz := uint64((d << 1) ^ (d >> 63))
		for zz >= 0x80 {
			out = append(out, byte(zz)|0x80)
			zz >>= 7
		}
		out = append(out, byte(zz))
	}
	var sum byte = 0x6B
	for _, b := range out {
		sum = (sum ^ b) + 0x13
	}
	return append(out, sum), nil
}

func DecodeDeltaFrame(raw []byte) ([]int64, error) {
	if len(raw) < 3 || raw[0] != FrameMagic {
		return nil, ErrBadFrame
	}
	count := int(raw[1])
	if count > MaxDeltas {
		return nil, ErrBadFrame
	}
	body, wantSum := raw[:len(raw)-1], raw[len(raw)-1]
	var gotSum byte = 0x6B
	for _, b := range body {
		gotSum = (gotSum ^ b) + 0x13
	}
	if gotSum != wantSum {
		return nil, ErrBadChecksum
	}
	pos := 2
	out := make([]int64, 0, count)
	for i := 0; i < count; i++ {
		var zz uint64
		var shift uint
		done := false
		for j := 0; j < 10 && pos < len(body); j++ {
			b := body[pos]
			pos++
			if j == 9 && b > 1 {
				return nil, ErrBadFrame
			}
			zz |= uint64(b&0x7F) << shift
			if b&0x80 == 0 {
				done = true
				break
			}
			shift += 7
		}
		if !done {
			return nil, ErrBadFrame
		}
		out = append(out, int64((zz>>1)^-(zz&1)))
	}
	if pos != len(body) {
		return nil, ErrBadFrame
	}
	return out, nil
}
