```ts
export interface GuardianJwt {
  alg: string;
  sub: string;
  chainTenant: string;
  role: 'observer' | 'proposer' | 'slash_guardian';
  nbfSec: number;
  expSec: number;
}

export async function slashValidatorEndpoint(
  jwt: GuardianJwt | null,
  targetChain: string,
  validatorKey: string,
  nowSec: number,
  slashFn: (chain: string, validatorKey: string) => Promise<string>,
): Promise<{ status: 200 | 401 | 403; evidenceId?: string; error?: string }> {
  if (!jwt || !jwt.sub.trim() || jwt.alg !== 'EdDSA') {
    return { status: 401, error: 'invalid_credentials' };
  }
  if (nowSec < jwt.nbfSec || nowSec >= jwt.expSec) {
    return { status: 401, error: 'outside_token_lifetime' };
  }
  if (jwt.chainTenant !== targetChain) {
    return { status: 403, error: 'cross_chain_denied' };
  }
  if (jwt.role !== 'slash_guardian') {
    return { status: 403, error: 'guardian_role_required' };
  }
  const evidenceId = await slashFn(targetChain, validatorKey);
  return { status: 200, evidenceId };
}
