Write a Rust `#[cfg(test)] mod tests` suite for `PasskeyEnrollmentGate` verifying cached `Replayed(id)` on duplicate `(rp_tenant, idem_key)` retries without incrementing `next_id`, `Conflict409` on mutated `cred_id` or `cose_alg`, and cross-RP key isolation:
```rust
use std::collections::HashMap;

#[derive(Debug, PartialEq, Eq)]
pub enum EnrollErr {
    InvalidKey,
    Conflict409,
}

#[derive(Debug, PartialEq, Eq)]
pub enum EnrollResult {
    Created(u64),
    Replayed(u64),
}

pub struct PasskeyEnrollmentGate {
    next_id: u64,
    records: HashMap<(String, String), ((String, i32), u64)>,
}

impl Default for PasskeyEnrollmentGate {
    fn default() -> Self {
        Self { next_id: 1, records: HashMap::new() }
    }
}

impl PasskeyEnrollmentGate {
    pub fn register(
        &mut self,
        rp_tenant: &str,
        idem_key: &str,
        cred_id: &str,
        cose_alg: i32,
    ) -> Result<EnrollResult, EnrollErr> {
        let k = idem_key.trim();
        if rp_tenant.is_empty() || k.len() < 6 {
            return Err(EnrollErr::InvalidKey);
        }
        let map_key = (rp_tenant.to_string(), k.to_string());
        if let Some(((saved_cred, saved_alg), row_id)) = self.records.get(&map_key) {
            if saved_cred != cred_id || *saved_alg != cose_alg {
                return Err(EnrollErr::Conflict409);
            }
            return Ok(EnrollResult::Replayed(*row_id));
        }
        let id = self.next_id;
        self.next_id += 1;
        self.records.insert(map_key, ((cred_id.to_string(), cose_alg), id));
        Ok(EnrollResult::Created(id))
    }
}
