Write a Go test suite using `httptest.NewServer` for `bridge/relayer_client.go` simulating `502` -> `429` (`Retry-After: 2`) -> `200`, verifying backoff durations on keyed `POST`, while proving unkeyed `POST` never retries on client timeout or `502`:
```go
package bridge

import (
	"bytes"
	"context"
	"net/http"
	"strconv"
	"time"
)

type RelayerClient struct {
	HTTP       *http.Client
	TryTimeout time.Duration
	Sleep      func(time.Duration)
}

func (rc *RelayerClient) Send(ctx context.Context, method, url, idemKey string, payload []byte) (*http.Response, error) {
	retryable := method == http.MethodGet || idemKey != ""
	maxTries := 1
	if retryable {
		maxTries = 3
	}
	for attempt := 1; attempt <= maxTries; attempt++ {
		tctx, cancel := context.WithTimeout(ctx, rc.TryTimeout)
		req, err := http.NewRequestWithContext(tctx, method, url, bytes.NewReader(payload))
		if err != nil {
			cancel()
			return nil, err
		}
		if idemKey != "" {
			req.Header.Set("Idempotency-Key", idemKey)
		}
		resp, err := rc.HTTP.Do(req)
		cancel()
		if err != nil {
			if attempt == maxTries {
				return nil, err
			}
			rc.Sleep(time.Duration(attempt) * 100 * time.Millisecond)
			continue
		}
		if (resp.StatusCode < 500 && resp.StatusCode != http.StatusTooManyRequests) || attempt == maxTries {
			return resp, nil
		}
		resp.Body.Close()
		if ra, err := strconv.Atoi(resp.Header.Get("Retry-After")); err == nil && ra > 0 {
			rc.Sleep(time.Duration(ra) * time.Second)
		} else {
			rc.Sleep(time.Duration(attempt) * 100 * time.Millisecond)
		}
	}
	return nil, context.Canceled
}
