Write a `pytest.mark.parametrize` boundary and security regression suite for `ratelimit/budget_header.py`:
```python
MAX_LIMIT = 1_000_000
MAX_WINDOW_SEC = 86_400

class RateHeaderError(ValueError):
    pass

def _strict_uint(raw: str) -> int:
    if not raw or not raw.isascii() or not raw.isdigit():
        raise RateHeaderError('non-digit rate header')
    if len(raw) > 1 and raw.startswith('0'):
        raise RateHeaderError('leading zero forbidden')
    return int(raw)

def consume_rate_budget_headers(
    limit_hdr: str,
    remaining_hdr: str,
    reset_hdr: str,
    now_epoch: int,
    cost_units: int,
) -> tuple[int, int]:
    if isinstance(now_epoch, bool) or isinstance(cost_units, bool):
        raise RateHeaderError('boolean integer forbidden')
    limit = _strict_uint(limit_hdr)
    remaining = _strict_uint(remaining_hdr)
    reset_at = _strict_uint(reset_hdr)
    if not (1 <= limit <= MAX_LIMIT):
        raise RateHeaderError('limit out of bounds')
    if remaining > limit:
        raise RateHeaderError('remaining exceeds limit')
    if not (1 <= cost_units <= remaining):
        raise RateHeaderError('insufficient remaining quota or bad cost')
    if reset_at <= now_epoch or (reset_at - now_epoch) > MAX_WINDOW_SEC:
        raise RateHeaderError('reset window out of bounds')
    return remaining - cost_units, reset_at - now_epoch
```

Write idiomatic table-driven Go tests (`t.Run`) for `jwtauth/audience_exchange.go` verifying HTTP status codes, the 2048-byte `MaxBytesReader` limit, `baseAudiences` slice non-aliasing, and `errors.Is` wrapping on `ErrWildcardAudience`:
```go
package jwtauth

import (
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"strings"
)

const MaxExchangeBody = 2048

var ErrWildcardAudience = errors.New("wildcard or empty audience forbidden")

type ExchangeReq struct {
	SubjectToken string   `json:"subject_token"`
	Audiences    []string `json:"audiences"`
}

func ParseAudienceExchange(w http.ResponseWriter, r *http.Request, baseAudiences []string) ([]string, int, error) {
	if r.Method != http.MethodPost {
		return nil, http.StatusMethodNotAllowed, fmt.Errorf("method %s disallowed", r.Method)
	}
	r.Body = http.MaxBytesReader(w, r.Body, MaxExchangeBody)
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	var req ExchangeReq
	if err := dec.Decode(&req); err != nil {
		var maxErr *http.MaxBytesError
		if errors.As(err, &maxErr) {
			return nil, http.StatusRequestEntityTooLarge, fmt.Errorf("exchange body: %w", err)
		}
		return nil, http.StatusBadRequest, fmt.Errorf("exchange decode: %w", err)
	}
	if req.SubjectToken == "" {
		return nil, http.StatusBadRequest, errors.New("missing subject_token")
	}
	for _, aud := range req.Audiences {
		if aud == "" || strings.Contains(aud, "*") {
			return nil, http.StatusUnprocessableEntity, fmt.Errorf("aud %q: %w", aud, ErrWildcardAudience)
		}
	}
	out := make([]string, 0, len(baseAudiences)+len(req.Audiences))
	out = append(out, baseAudiences...)
	out = append(out, req.Audiences...)
	return out, http.StatusOK, nil
}
