Write a Rust `#[cfg(test)] mod tests` suite for `AuthenticatorGuard` verifying `checked_add` counter overflow returning `None`, `FromStr` malformed input rejection, `KeyStatus` invalid transitions, and stack-only `[u32; 4]` sign-count ring tracking:
```rust
use std::str::FromStr;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum KeyStatus {
    Enrolled,
    Active,
    Quarantined,
    Tombstoned,
}

#[derive(Debug, PartialEq, Eq)]
pub enum GuardErr {
    BadSeed,
    InvalidTransition(KeyStatus, KeyStatus),
    KeyNotActive,
}

pub struct AuthenticatorGuard {
    sign_count: u32,
    status: KeyStatus,
    audit_counts: [u32; 4],
    pos: usize,
}

impl FromStr for AuthenticatorGuard {
    type Err = GuardErr;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let rest = s.strip_prefix("cnt=").ok_or(GuardErr::BadSeed)?;
        let cnt: u32 = rest.parse().map_err(|_| GuardErr::BadSeed)?;
        Ok(Self { sign_count: cnt, status: KeyStatus::Enrolled, audit_counts: [0; 4], pos: 0 })
    }
}

impl AuthenticatorGuard {
    pub fn transition(&mut self, next: KeyStatus) -> Result<(), GuardErr> {
        let ok = matches!(
            (self.status, next),
            (KeyStatus::Enrolled, KeyStatus::Active)
                | (KeyStatus::Active, KeyStatus::Quarantined)
                | (KeyStatus::Quarantined, KeyStatus::Active)
                | (KeyStatus::Active, KeyStatus::Tombstoned)
                | (KeyStatus::Quarantined, KeyStatus::Tombstoned)
        );
        if !ok {
            return Err(GuardErr::InvalidTransition(self.status, next));
        }
        self.status = next;
        Ok(())
    }

    pub fn advance_by(&mut self, delta: u32) -> Result<Option<u32>, GuardErr> {
        if self.status != KeyStatus::Active {
            return Err(GuardErr::KeyNotActive);
        }
        if delta == 0 {
            return Ok(None);
        }
        let Some(next_cnt) = self.sign_count.checked_add(delta) else {
            return Ok(None);
        };
        self.sign_count = next_cnt;
        self.audit_counts[self.pos % 4] = next_cnt;
        self.pos = self.pos.wrapping_add(1);
        Ok(Some(next_cnt))
    }
}
