    #[test]
    fn from_str_parses_u32_and_rejects_malformed_seeds() {
        let g: AuthenticatorGuard = "cnt=0".parse().unwrap();
        assert_eq!(g.status, KeyStatus::Enrolled);

        for bad in ["", "0", "cnt=-1", "cnt=4294967296", "cnt=xyz"] {
