        assert_eq!(g.advance_by(1), Err(GuardErr::KeyNotActive));

        g.transition(KeyStatus::Tombstoned).unwrap();
        assert_eq!(
            g.transition(KeyStatus::Active),
            Err(GuardErr::InvalidTransition(KeyStatus::Tombstoned, KeyStatus::Active))
        );
