Write a Vitest security regression suite for `src/ledger/submitAnchorRoot.ts` covering strict Zod rejection of injected `skipProofVerify` properties, `Origin` validation, 60-second rollup cooldown reset via `vi.useFakeTimers()`, and `AbortSignal` cancellation:
```ts
import { z } from 'zod';

const AnchorSchema = z.object({
  l2Height: z.number().int().positive(),
  stateRoot: z.string().regex(/^0x[0-9a-f]{64}$/),
}).strict();

const SEQUENCER_ORIGINS = new Set(['https://seq.rollup.internal']);

export class RollupAnchorGateway {
  private nextAllowedAt = new Map<string, number>();

  constructor(private postToL1: (rollupId: string, height: number, root: string, sig?: AbortSignal) => Promise<string>) {}

  async anchor(rollupId: string, origin: string | undefined, body: unknown, signal?: AbortSignal) {
    if (!origin || !SEQUENCER_ORIGINS.has(origin)) {
      return { status: 403 as const, error: 'forbidden_origin' };
    }
    const parsed = AnchorSchema.safeParse(body);
    if (!parsed.success) {
      return { status: 400 as const, error: 'invalid_anchor_payload' };
    }
    const now = Date.now();
    const lockUntil = this.nextAllowedAt.get(rollupId) ?? 0;
    if (now < lockUntil) {
      return { status: 429 as const, error: 'anchor_cooldown_active' };
    }
    this.nextAllowedAt.set(rollupId, now + 60_000);
    signal?.throwIfAborted();
    const l1Tx = await this.postToL1(rollupId, parsed.data.l2Height, parsed.data.stateRoot, signal);
    return { status: 201 as const, l1Tx };
  }
}
