Write a Vitest concurrent stress test suite for `src/ratelimit/boundedSemaphore.ts` proving 30 overlapping async tasks never exceed `maxActive = 4` concurrent executions, reject immediately beyond `maxQueue = 6`, and release permits cleanly when tasks throw:
```ts
export class QueueSaturatedError extends Error {
  constructor() {
    super('rate semaphore queue saturated');
  }
}

export class BoundedAsyncSemaphore {
  private active = 0;
  private waiters: Array<() => void> = [];

  constructor(
    private readonly maxActive: number,
    private readonly maxQueue: number,
  ) {}

  async run<T>(fn: () => Promise<T>): Promise<T> {
    if (this.active >= this.maxActive) {
      if (this.waiters.length >= this.maxQueue) {
        throw new QueueSaturatedError();
      }
      await new Promise<void>((resolve) => this.waiters.push(resolve));
    }
    this.active++;
    try {
      return await fn();
    } finally {
      this.active--;
      const next = this.waiters.shift();
      if (next) next();
    }
  }

  inFlight(): number {
    return this.active;
  }
}
```

