Write a Rust `#[cfg(test)] mod tests` round-trip and malformed-packet rejection suite for the fixed 64-byte CTAP-style binary HID init frame codec below:
```rust
#[derive(Debug, PartialEq, Eq)]
pub enum HidFrameErr {
    ReservedChannel,
    MissingCmdBit,
    PayloadTooLarge,
    BadReportSize,
    NonZeroPadding,
    ParityMismatch,
}

const REPORT_LEN: usize = 64;
const MAX_INIT_PAYLOAD: usize = 56;

pub fn encode_hid_init(cid: u32, cmd: u8, payload: &[u8]) -> Result<[u8; REPORT_LEN], HidFrameErr> {
    if cid == 0 || cid == u32::MAX {
        return Err(HidFrameErr::ReservedChannel);
    }
    if cmd & 0x80 == 0 {
        return Err(HidFrameErr::MissingCmdBit);
    }
    if payload.len() > MAX_INIT_PAYLOAD {
        return Err(HidFrameErr::PayloadTooLarge);
    }
    let mut pkt = [0_u8; REPORT_LEN];
    pkt[0..4].copy_from_slice(&cid.to_be_bytes());
    pkt[4] = cmd;
    pkt[5..7].copy_from_slice(&(payload.len() as u16).to_be_bytes());
    pkt[7..7 + payload.len()].copy_from_slice(payload);
    pkt[63] = pkt[0..63].iter().fold(0x55_u8, |a, &b| a ^ b);
    Ok(pkt)
}

pub fn decode_hid_init(raw: &[u8]) -> Result<(u32, u8, Vec<u8>), HidFrameErr> {
    if raw.len() != REPORT_LEN {
        return Err(HidFrameErr::BadReportSize);
    }
    let expected_parity = raw[0..63].iter().fold(0x55_u8, |a, &b| a ^ b);
    if raw[63] != expected_parity {
        return Err(HidFrameErr::ParityMismatch);
    }
    let cid = u32::from_be_bytes([raw[0], raw[1], raw[2], raw[3]]);
    if cid == 0 || cid == u32::MAX {
        return Err(HidFrameErr::ReservedChannel);
    }
    let cmd = raw[4];
    if cmd & 0x80 == 0 {
        return Err(HidFrameErr::MissingCmdBit);
    }
    let plen = u16::from_be_bytes([raw[5], raw[6]]) as usize;
    if plen > MAX_INIT_PAYLOAD {
        return Err(HidFrameErr::PayloadTooLarge);
    }
    if raw[7 + plen..63].iter().any(|&b| b != 0) {
        return Err(HidFrameErr::NonZeroPadding);
    }
    Ok((cid, cmd, raw[7..7 + plen].to_vec()))
}
