            let report = encode_hid_init(0x0102_0304, 0x90, &data).unwrap();
            let (cid, cmd, got) = decode_hid_init(&report).unwrap();
            assert_eq!((cid, cmd, got), (0x0102_0304, 0x90, data));
        }
    }

    #[test]
    fn rejects_reserved_channels_bad_cmd_bit_and_oversized_payloads() {
        assert_eq!(encode_hid_init(0, 0x81, b"ok"), Err(HidFrameErr::ReservedChannel));
        assert_eq!(encode_hid_init(u32::MAX, 0x81, b"ok"), Err(HidFrameErr::ReservedChannel));
        assert_eq!(encode_hid_init(1, 0x01, b"ok"), Err(HidFrameErr::MissingCmdBit));
        assert_eq!(encode_hid_init(1, 0x81, &[0_u8; 57]), Err(HidFrameErr::PayloadTooLarge));
    }

    #[test]
    fn decode_rejects_bad_size_dirty_padding_forged_len_and_parity_flip() {
        assert_eq!(decode_hid_init(&[0_u8; 63]), Err(HidFrameErr::BadReportSize));

        let mut base = encode_hid_init(42, 0x86, b"fido").unwrap();
        let mut flipped = base;
        flipped[8] ^= 0x01;
        assert_eq!(decode_hid_init(&flipped), Err(HidFrameErr::ParityMismatch));

        base[30] = 0xFF;
        reseal(&mut base);
        assert_eq!(decode_hid_init(&base), Err(HidFrameErr::NonZeroPadding));

        let mut bad_len = encode_hid_init(42, 0x86, b"").unwrap();
        bad_len[5..7].copy_from_slice(&57_u16.to_be_bytes());
        reseal(&mut bad_len);
        assert_eq!(decode_hid_init(&bad_len), Err(HidFrameErr::PayloadTooLarge));
    }
}
