Write a `pytest` RBAC + JWT claims matrix suite for `webauthn_admin/reset_passkeys.py` covering `(None_claims, wrong_alg, immature_nbf, expired_exp, cross_rp_tenant, helpdesk_role, user_role, identity_sec_lead_role)` and asserting fail-closed `401`/`403` responses with zero `wipe_fn` calls:
```python
from dataclasses import dataclass
from typing import Callable

@dataclass(frozen=True)
class AdminAssertion:
    alg: str
    sub: str
    rp_tenant: str
    role: str
    nbf_ts: int
    exp_ts: int

def emergency_wipe_passkeys(
    assertion: AdminAssertion | None,
    target_rp_tenant: str,
    target_user_id: str,
    now_ts: int,
    wipe_fn: Callable[[str, str, str], int],
) -> tuple[int, dict]:
    if assertion is None or not assertion.sub.strip() or assertion.alg != 'ES256':
        return 401, {'error': 'unauthenticated_or_bad_alg'}
    if now_ts < assertion.nbf_ts or now_ts >= assertion.exp_ts:
        return 401, {'error': 'assertion_outside_window'}
    if assertion.rp_tenant != target_rp_tenant:
        return 403, {'error': 'rp_tenant_mismatch'}
    if assertion.role != 'identity_sec_lead':
        return 403, {'error': 'insufficient_admin_role'}
    removed = wipe_fn(target_rp_tenant, target_user_id, assertion.sub)
    return 200, {'revoked_count': removed}
