Write a Go test suite for `ledger/anchor_dedup.go` verifying first-call `201` execution, cached `txHash` replay across concurrent goroutines sharing `(tenantID, idemKey)`, cross-tenant key isolation, and `409 Conflict` (`ErrAnchorMismatch`) on mutated state roots:
```go
package ledger

import (
	"crypto/sha256"
	"encoding/binary"
	"errors"
	"net/http"
	"sync"
)

var ErrAnchorMismatch = errors.New("idempotency key reused with different height or state root")

type anchorEntry struct {
	fingerprint [32]byte
	txHash      string
}

type AnchorCoordinator struct {
	mu     sync.Mutex
	seen   map[string]anchorEntry
	submit func(tenantID string, height uint64, root [32]byte) string
}

func NewAnchorCoordinator(submit func(string, uint64, [32]byte) string) *AnchorCoordinator {
	return &AnchorCoordinator{seen: make(map[string]anchorEntry), submit: submit}
}

func (ac *AnchorCoordinator) Anchor(tenantID, idemKey string, height uint64, root [32]byte) (int, string, error) {
	if tenantID == "" || len(idemKey) < 6 {
		return http.StatusBadRequest, "", errors.New("bad tenant or idemKey")
	}
	var buf [40]byte
	binary.BigEndian.PutUint64(buf[0:8], height)
	copy(buf[8:40], root[:])
	fp := sha256.Sum256(buf[:])

	slot := tenantID + "|" + idemKey
	ac.mu.Lock()
	defer ac.mu.Unlock()
	if prev, ok := ac.seen[slot]; ok {
		if prev.fingerprint != fp {
			return http.StatusConflict, "", ErrAnchorMismatch
		}
		return http.StatusOK, prev.txHash, nil
	}
	tx := ac.submit(tenantID, height, root)
	ac.seen[slot] = anchorEntry{fingerprint: fp, txHash: tx}
	return http.StatusCreated, tx, nil
}
