package ledger

import (
	"errors"
	"net/http"
	"sync"
	"sync/atomic"
	"testing"
)

func TestAnchorCoordinatorReplayConflictAndTenantIsolation(t *testing.T) {
	var submits atomic.Int32
	ac := NewAnchorCoordinator(func(ten string, _ uint64, _ [32]byte) string {
		n := submits.Add(1)
		return ten + "-tx-" + string(rune('0'+n))
	})

	rootA := [32]byte{1, 2, 3}
	var wg sync.WaitGroup
	var created, replayed atomic.Int32

	for i := 0; i < 16; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			code, tx, err := ac.Anchor("rollup-a", "idem-0001", 500, rootA)
			if err != nil || tx != "rollup-a-tx-1" {
				t.Errorf("unexpected (%d, %q, %v)", code, tx, err)
			}
			if code == http.StatusCreated {
				created.Add(1)
			} else if code == http.StatusOK {
				replayed.Add(1)
			}
		}()
	}
	wg.Wait()

	if created.Load() != 1 || replayed.Load() != 15 || submits.Load() != 1 {
		t.Fatalf("created=%d replayed=%d submits=%d", created.Load(), replayed.Load(), submits.Load())
	}

	if code, _, err := ac.Anchor("rollup-a", "idem-0001", 501, rootA); code != http.StatusConflict || !errors.Is(err, ErrAnchorMismatch) {
		t.Fatalf("mutated height got (%d, %v), want 409 ErrAnchorMismatch", code, err)
	}
	rootB := [32]byte{9, 9, 9}
	if code, _, err := ac.Anchor("rollup-a", "idem-0001", 500, rootB); code != http.StatusConflict || !errors.Is(err, ErrAnchorMismatch) {
		t.Fatalf("mutated root got (%d, %v), want 409 ErrAnchorMismatch", code, err)
	}

	if code, _, err := ac.Anchor("rollup-b", "idem-0001", 999, rootB); code != http.StatusCreated || err != nil {
		t.Fatalf("distinct tenant with same key got (%d, %v), want 201", code, err)
	}
	if submits.Load() != 2 {
		t.Fatalf("expected 2 total submits across 2 tenants, got %d", submits.Load())
	}
}
