Write a Rust `#[cfg(test)] mod tests` suite for `call_validator_rpc` testing capped exponential backoff (`1000ms` cap) and `Retry-After` overrides on `429` for `RpcOp::Query` and keyed `RpcOp::BroadcastTx`, while proving unkeyed `RpcOp::BroadcastTx` never retries on `RpcTimeout` or `503`:
```rust
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RpcOp {
    Query,
    BroadcastTx,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RpcResponse {
    pub status: u16,
    pub retry_after_sec: Option<u64>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RpcTimeout;

pub fn call_validator_rpc<T, S>(
    op: RpcOp,
    idem_key: Option<&str>,
    mut transport: T,
    mut sleep_ms: S,
) -> Result<RpcResponse, RpcTimeout>
where
    T: FnMut(Option<&str>) -> Result<RpcResponse, RpcTimeout>,
    S: FnMut(u64),
{
    let can_retry = op == RpcOp::Query || idem_key.is_some_and(|k| !k.trim().is_empty());
    let max_tries: u32 = if can_retry { 4 } else { 1 };

    for attempt in 1..=max_tries {
        let exp_wait = (300_u64 << (attempt - 1)).min(1_000);
        match transport(idem_key) {
            Ok(resp) if (resp.status < 500 && resp.status != 429) || attempt == max_tries => {
                return Ok(resp);
            }
            Ok(resp) => {
                let wait = resp.retry_after_sec.filter(|&s| s > 0).map_or(exp_wait, |s| s * 1_000);
                sleep_ms(wait);
            }
            Err(RpcTimeout) if attempt == max_tries => return Err(RpcTimeout),
            Err(RpcTimeout) => sleep_ms(exp_wait),
        }
    }
    unreachable!()
}
