#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::VecDeque;

    #[test]
    fn keyed_broadcast_caps_exponential_backoff_and_respects_retry_after() {
        let mut replies = VecDeque::from([
            Ok(RpcResponse { status: 503, retry_after_sec: None }),
            Ok(RpcResponse { status: 429, retry_after_sec: Some(4) }),
            Err(RpcTimeout),
            Ok(RpcResponse { status: 200, retry_after_sec: None }),
        ]);
        let mut sleeps = Vec::new();
        let mut seen_keys = Vec::new();

        let res = call_validator_rpc(
            RpcOp::BroadcastTx,
            Some("tx-key-88"),
            |k| {
                seen_keys.push(k.map(str::to_owned));
                replies.pop_front().unwrap()
            },
            |ms| sleeps.push(ms),
        );

        assert_eq!(res, Ok(RpcResponse { status: 200, retry_after_sec: None }));
        assert_eq!(sleeps, vec![300, 4_000, 1_000]);
        assert_eq!(seen_keys.len(), 4);
    }

    #[test]
    fn unkeyed_broadcast_never_retries_on_timeout_or_503() {
        let mut sleeps = Vec::new();
        let mut tries = 0;

        let res_to = call_validator_rpc(
            RpcOp::BroadcastTx,
            None,
            |_| {
                tries += 1;
                Err(RpcTimeout)
            },
            |ms| sleeps.push(ms),
        );
        assert_eq!(res_to, Err(RpcTimeout));
        assert_eq!(tries, 1);
        assert!(sleeps.is_empty());

        let mut tries_503 = 0;
        let res_503 = call_validator_rpc(
            RpcOp::BroadcastTx,
            Some("   "),
            |_| {
                tries_503 += 1;
                Ok(RpcResponse { status: 503, retry_after_sec: None })
            },
            |ms| sleeps.push(ms),
        );
        assert_eq!(res_503, Ok(RpcResponse { status: 503, retry_after_sec: None }));
        assert_eq!(tries_503, 1);
        assert!(sleeps.is_empty());
    }
}
